def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    border = int(round(params['colors'][1]))
    step = int(round(params['step'][0]))
    out = grid.copy()
    if step <= 0:
        return out
    height, width = grid.shape
    for k in range(len(params['sizes'])):
        size = int(round(params['sizes'][k]))
        fill = int(round(params['fills'][k]))
        if size <= step or size > height or size > width:
            continue
        for r in range(height - size + step):
            for c in range(width - size + step):
                block = grid[r:r + size, c:c + size]
                if np.all(block[0, :] == border) and np.all(block[-step, :] == border) and np.all(block[:, 0] == border) and np.all(block[:, -step] == border):
                    interior = grid[r + step:r + size - step, c + step:c + size - step]
                    out[r + step:r + size - step, c + step:c + size - step] = np.where(interior == background, fill, interior)
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    period = int(round(params['rule'][1]))
    row_step = int(round(params['rule'][2]))
    col_step = int(round(params['rule'][3]))
    if period <= 0:
        return grid.copy()
    colors = {}
    height, width = grid.shape
    for row in range(height):
        for col in range(width):
            color = int(grid[row, col])
            if color != background:
                residue = (row_step * row + col_step * col) % period
                if residue in colors and colors[residue] != color:
                    return grid.copy()
                colors[residue] = color
    if len(colors) != period:
        return grid.copy()
    output = grid.copy()
    for row in range(height):
        for col in range(width):
            residue = (row_step * row + col_step * col) % period
            output[row, col] = colors[residue]
    return output

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    shift = int(round(params['shift'][0]))
    neighbors = []
    for pair in params['neighbors']:
        neighbors.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    out = np.full(grid.shape, bg, dtype=int)
    seen = set()
    for r in range(height):
        for c in range(width):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            color = int(grid[r, c])
            cells = [(r, c)]
            seen.add((r, c))
            index = 0
            while index < len(cells):
                y, x = cells[index]
                index += 1
                for dy, dx in neighbors:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < height and 0 <= nx < width:
                        if (ny, nx) not in seen and grid[ny, nx] == color:
                            seen.add((ny, nx))
                            cells.append((ny, nx))
            bottom = max(y for y, x in cells)
            right = max(x for y, x in cells)
            for y, x in cells:
                target = x if y == bottom else min(x + shift, right)
                if 0 <= target < width:
                    out[y, target] = color
    return out

def run(params, grid, demos):
    foreground = int(round(params['colors'][0]))
    palette = [int(round(v)) for v in params['palette']]
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['directions']]
    height, width = grid.shape
    result = grid.copy()
    visited = set()
    for row in range(height):
        for col in range(width):
            if grid[row, col] != foreground or (row, col) in visited:
                continue
            component = {(row, col)}
            visited.add((row, col))
            queue = [(row, col)]
            while queue:
                r, c = queue.pop()
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < height and 0 <= nc < width and (nr, nc) not in visited and grid[nr, nc] == foreground:
                        visited.add((nr, nc))
                        component.add((nr, nc))
                        queue.append((nr, nc))
            top = min(r for r, c in component)
            bottom = max(r for r, c in component)
            left = min(c for r, c in component)
            right = max(c for r, c in component)
            empty_seen = set()
            holes = 0
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    if (r, c) in component or (r, c) in empty_seen:
                        continue
                    empty_seen.add((r, c))
                    queue = [(r, c)]
                    boundary = False
                    while queue:
                        er, ec = queue.pop()
                        if er == top or er == bottom or ec == left or ec == right:
                            boundary = True
                        for dr, dc in directions:
                            nr, nc = er + dr, ec + dc
                            if top <= nr <= bottom and left <= nc <= right and (nr, nc) not in component and (nr, nc) not in empty_seen:
                                empty_seen.add((nr, nc))
                                queue.append((nr, nc))
                    if not boundary:
                        holes += 1
            color = palette[holes] if holes < len(palette) else foreground
            for r, c in component:
                result[r, c] = color
    return result

def run(params, grid, demos):
    out = grid.copy()
    background = int(round(params['background'][0]))
    for k in range(len(params['colors'])):
        seed = int(round(params['colors'][k][0]))
        paint = int(round(params['colors'][k][1]))
        for r, c in np.argwhere(grid == seed):
            for offset in params['offsets'][k]:
                rr = r + int(round(offset[0]))
                cc = c + int(round(offset[1]))
                if 0 <= rr < grid.shape[0] and 0 <= cc < grid.shape[1]:
                    if grid[rr, cc] == background:
                        out[rr, cc] = paint
    return out

def run(params, grid, demos):
    positions = []
    palette = []
    targets = []
    for i in range(len(params['mapping'])):
        r = int(round(params['positions'][i][0]))
        c = int(round(params['positions'][i][1]))
        j = int(round(params['mapping'][i]))
        if r < 0 or c < 0 or r >= grid.shape[0] or c >= grid.shape[1] or j < 0 or j >= len(params['mapping']):
            return grid.copy()
        positions.append((r, c))
        palette.append(int(grid[r, c]))
        targets.append(j)
    result = grid.copy()
    for i in range(len(palette)):
        result[grid == palette[i]] = palette[targets[i]]
    for r, c in positions:
        result[r, c] = grid[r, c]
    return result

def run(params, grid, demos):
    palette = [int(round(v)) for v in params['palette']]
    bg = int(round(params['background'][0]))
    neighbors = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    axes = [(int(round(v[0])), int(round(v[1]))) for v in params['axes']]
    diagonals = [(int(round(v[0])), int(round(v[1]))) for v in params['diagonals']]
    h, w = grid.shape
    out = np.zeros(grid.shape, dtype=int)
    for r in range(h):
        for c in range(w):
            out[r, c] = palette[int(grid[r, c])]
    for r in range(h):
        for c in range(w):
            center = palette[int(grid[r, c])]
            if center == bg:
                continue
            arms = []
            valid = True
            for dr, dc in neighbors:
                rr, cc = r + dr, c + dc
                if rr < 0 or rr >= h or cc < 0 or cc >= w:
                    valid = False
                    break
                arms.append(palette[int(grid[rr, cc])])
            if not valid or not arms:
                continue
            arm = arms[0]
            if arm == bg or arm == center or not all(v == arm for v in arms):
                continue
            for dr, dc in axes:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr, cc] = arm
            for dr, dc in diagonals:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr, cc] = center
    return out

def run(params, grid, demos):
    marker = int(round(params['colors'][0]))
    object_color = int(round(params['colors'][1]))
    unit = int(round(params['unit'][0]))
    directions = [(int(round(a)), int(round(b))) for a, b in params['directions']]
    height, width = grid.shape
    out = grid.copy()
    lines = np.zeros(grid.shape)
    for r in range(height):
        if grid[r, 0] == marker and grid[r, width - unit] == marker:
            lines[r, :] = unit
    for c in range(width):
        if grid[0, c] == marker and grid[height - unit, c] == marker:
            lines[:, c] = unit
    seen = set()
    for r in range(height):
        for c in range(width):
            if grid[r, c] != object_color or (r, c) in seen:
                continue
            component = [(r, c)]
            seen.add((r, c))
            pending = [(r, c)]
            hit = False
            while pending:
                a, b = pending.pop()
                if bool(lines[a, b]):
                    hit = True
                for dr, dc in directions:
                    x, y = a + dr, b + dc
                    if 0 <= x < height and 0 <= y < width:
                        if grid[x, y] == object_color and (x, y) not in seen:
                            seen.add((x, y))
                            component.append((x, y))
                            pending.append((x, y))
            if hit:
                for a, b in component:
                    out[a, b] = marker
    out[lines != 0] = marker
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    center_color = int(round(params['rule'][1]))
    radius = int(round(params['rule'][2]))
    divisor = int(round(params['rule'][3]))
    count = int(round(params['rule'][4]))
    out = grid.copy()
    points = np.argwhere(grid != bg)
    if len(points) != count or divisor <= 0 or radius <= 0:
        return out
    if len(points) == 0:
        return out
    cr = int((np.min(points[:, 0]) + np.max(points[:, 0])) // divisor)
    cc = int((np.min(points[:, 1]) + np.max(points[:, 1])) // divisor)
    if not (0 <= cr < grid.shape[0] and 0 <= cc < grid.shape[1]):
        return out
    if not (0 <= center_color <= 9):
        return out
    for point in points:
        r = int(point[0])
        c = int(point[1])
        dr = r - cr
        dc = c - cc
        if dr == 0 or dc == 0:
            return grid.copy()
        nr = cr + radius * (dr // abs(dr))
        nc = cc + radius * (dc // abs(dc))
        if not (0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]):
            return grid.copy()
        out[nr, nc] = grid[r, c]
    out[cr, cc] = center_color
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    wall = int(round(params['rule'][1]))
    forward = int(round(params['rule'][2]))
    backward = int(round(params['rule'][3]))
    out = grid.copy()
    h, w = grid.shape
    dr, dc = 0, 0
    if np.all(grid[0, :] == wall):
        dr = forward
    elif np.all(grid[-1, :] == wall):
        dr = backward
    elif np.all(grid[:, 0] == wall):
        dc = forward
    elif np.all(grid[:, -1] == wall):
        dc = backward
    if dr == 0 and dc == 0:
        return out
    for r in range(h):
        for c in range(w):
            if grid[r, c] != bg:
                continue
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                color = int(grid[rr, cc])
                if color == wall:
                    break
                if color != bg:
                    out[r, c] = color
                    break
                rr += dr
                cc += dc
    return out

def run(params, grid, demos):
    seed = int(round(params['colors'][0]))
    center = int(round(params['colors'][1]))
    corner = int(round(params['colors'][2]))
    horizontal = int(round(params['axes'][0]))
    vertical = int(round(params['axes'][1]))
    offsets = []
    for pair in params['corners']:
        offsets.append((int(round(pair[0])), int(round(pair[1]))))
    out = grid.copy()
    points = np.argwhere(grid == seed)
    h, w = grid.shape
    for r, c in points:
        if horizontal:
            out[r, :] = seed
        if vertical:
            out[:, c] = seed
    for r, c in points:
        for dr, dc in offsets:
            rr = r + dr
            cc = c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr, cc] = corner
    for r, c in points:
        out[r, c] = center
    return out

def run(params, grid, demos):
    zero = int(round(params['rule'][0]))
    one = int(round(params['rule'][1]))
    spacing = int(round(params['rule'][2]))
    intersection = int(round(params['rule'][3]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    colors, counts = np.unique(grid, return_counts=True)
    background = int(colors[np.argmax(counts)])
    remaining = np.where(colors == background, zero, counts)
    body = int(colors[np.argmax(remaining)])
    height, width = grid.shape
    result = grid.copy()
    borders = []
    markers = np.argwhere(np.logical_and(grid != background, grid != body))
    for position in markers:
        row, col = int(position[0]), int(position[1])
        color = int(grid[row, col])
        chosen = None
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if zero <= nr < height and zero <= nc < width:
                if grid[nr, nc] == background:
                    chosen = (dr, dc)
        if chosen is None:
            continue
        dr, dc = chosen
        for distance in range(one, max(height, width) + one):
            nr = row + dr * spacing * distance
            nc = col + dc * spacing * distance
            if zero <= nr < height and zero <= nc < width:
                result[nr, nc] = color
        if dr < zero:
            borders.append((zero, zero, color))
        elif dr > zero:
            borders.append((zero, height - one, color))
        elif dc < zero:
            borders.append((one, zero, color))
        elif dc > zero:
            borders.append((one, width - one, color))
    painted = np.zeros(grid.shape, dtype=int)
    for axis, edge, color in borders:
        if axis == zero:
            for col in range(width):
                if painted[edge, col] != zero and result[edge, col] != color:
                    result[edge, col] = intersection
                else:
                    result[edge, col] = color
                painted[edge, col] = one
        else:
            for row in range(height):
                if painted[row, edge] != zero and result[row, edge] != color:
                    result[row, edge] = intersection
                else:
                    result[row, edge] = color
                painted[row, edge] = one
    return result

def run(params, grid, demos):
    out = grid.copy()
    for i in range(len(params['colors'])):
        color = int(round(params['colors'][i]))
        axis = int(round(params['axes'][i]))
        for position in np.argwhere(grid == color):
            if axis == 0:
                out[int(position[0]), :] = color
            else:
                out[:, int(position[1])] = color
    return out

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    mark = int(round(params['colors'][1]))
    minimum = int(round(params['geometry'][0]))
    low = int(round(params['geometry'][1]))
    high = int(round(params['geometry'][2]))
    directions = []
    for pair in params['neighbors']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    out = grid.copy()
    height, width = grid.shape
    seen = set()
    for row in range(height):
        for col in range(width):
            if grid[row, col] == bg or (row, col) in seen:
                continue
            color = grid[row, col]
            component = [(row, col)]
            seen.add((row, col))
            position = 0
            while position < len(component):
                r, c = component[position]
                position += 1
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if (nr, nc) not in seen and grid[nr, nc] == color:
                            seen.add((nr, nc))
                            component.append((nr, nc))
            top = min(p[0] for p in component)
            bottom = max(p[0] for p in component)
            left = min(p[1] for p in component)
            right = max(p[1] for p in component)
            side = bottom - top + high
            if side < minimum or side != right - left + high:
                continue
            valid = True
            for r in range(top, bottom + high):
                if grid[r, left] != color or grid[r, right] != color:
                    valid = False
            for c in range(left, right + high):
                if grid[top, c] != color or grid[bottom, c] != color:
                    valid = False
            if not valid:
                continue
            for r, dr in [(top, low), (bottom, high)]:
                for c, dc in [(left, low), (right, high)]:
                    for nr, nc in [(r + dr, c), (r, c + dc)]:
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr, nc] == bg:
                                out[nr, nc] = mark
    return out

def run(params, grid, demos):
    size = max(1, int(round(params['config'][0])))
    step = max(1, int(round(params['config'][1])))
    marker = int(round(params['config'][2]))
    out = grid.copy()
    key = None
    for r in range(0, grid.shape[0], step):
        for c in range(0, grid.shape[1], step):
            block = grid[r:r+size, c:c+size]
            if block.shape == (size, size) and not np.any(block == marker):
                key = block.copy()
                break
        if key is not None:
            break
    if key is None:
        return out
    for r in range(0, grid.shape[0], step):
        for c in range(0, grid.shape[1], step):
            block = grid[r:r+size, c:c+size]
            if block.shape == (size, size):
                i = min(r // step, key.shape[0] - 1)
                j = min(c // step, key.shape[1] - 1)
                out[r:r+size, c:c+size] = key[i, j]
    return out

def run(params, grid, demos):
    bg = int(round(params['config'][0]))
    panel = int(round(params['config'][1]))
    size = int(round(params['config'][2]))
    low = int(round(params['config'][3]))
    high = int(round(params['config'][4]))
    if size <= 0 or size > 30 or low < 0 or high >= size:
        return grid.copy()
    area = np.argwhere(grid == panel)
    if len(area) == 0:
        return grid.copy()
    center = np.mean(area, axis=0)
    out = np.full((size, size), bg, dtype=int)
    for color in np.unique(grid):
        if color != bg and color != panel:
            points = np.argwhere(grid == color)
            position = np.mean(points, axis=0)
            row = high if position[0] > center[0] else low
            col = high if position[1] > center[1] else low
            out[row, col] = color
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    step = int(round(params['rule'][1]))
    margin = int(round(params['rule'][2]))
    edge_rods = int(round(params['rule'][3]))
    offsets = params['neighbors']
    h, w = grid.shape
    out = np.full((h, w), bg, dtype=int)
    out[0, :] = grid[0, :]
    out[h - step, :] = grid[h - step, :]
    seen = set()
    for r in range(margin, h - margin):
        for c in range(w):
            color = int(grid[r, c])
            if color == bg or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            pos = 0
            while pos < len(cells):
                a, b = cells[pos]
                pos += 1
                for k in range(len(offsets)):
                    dr = int(round(offsets[k][0]))
                    dc = int(round(offsets[k][1]))
                    nr, nc = a + dr, b + dc
                    if margin <= nr < h - margin and 0 <= nc < w:
                        if (nr, nc) not in seen and int(grid[nr, nc]) == color:
                            seen.add((nr, nc))
                            cells.append((nr, nc))
            low = min(a for a, b in cells)
            high = max(a for a, b in cells)
            if color == int(grid[0, 0]):
                shift = margin - low
            elif color == int(grid[h - step, 0]):
                shift = h - margin - step - high
            else:
                shift = 0
            for a, b in cells:
                nr = a + shift
                if 0 <= nr < h:
                    out[nr, b] = color
            if edge_rods == step and color == int(grid[h - step, 0]):
                if all(b == w - step for a, b in cells):
                    for a in range(low, h - margin):
                        out[a, w - step] = color
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    coverage = float(params['rule'][1])
    size = int(round(params['rule'][2]))
    height, width = grid.shape
    winner = background
    for value in np.unique(grid):
        color = int(value)
        if color != background:
            mask = grid == color
            horizontal = np.any(np.sum(mask, axis=1) == width * coverage)
            vertical = np.any(np.sum(mask, axis=0) == height * coverage)
            if horizontal or vertical:
                winner = color
                break
    return np.full((size, size), winner)

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    erase = int(round(params['colors'][1]))
    singleton = int(round(params['counts'][0]))
    minimum = int(round(params['counts'][1]))
    neighbors = []
    for row in params['neighbors']:
        neighbors.append((int(round(row[0])), int(round(row[1]))))
    height, width = grid.shape
    seen = set()
    objects = []
    for r in range(height):
        for c in range(width):
            if (r, c) in seen or grid[r, c] == bg or grid[r, c] == erase:
                continue
            seen.add((r, c))
            pending = [(r, c)]
            component = []
            while pending:
                y, x = pending.pop()
                component.append((y, x))
                for dy, dx in neighbors:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < height and 0 <= xx < width:
                        if (yy, xx) not in seen and grid[yy, xx] != bg and grid[yy, xx] != erase:
                            seen.add((yy, xx))
                            pending.append((yy, xx))
            if len(component) > minimum:
                objects.append(component)
    output = np.full(grid.shape, bg, dtype=int)
    for component in objects:
        counts = {}
        for y, x in component:
            color = int(grid[y, x])
            counts[color] = counts.get(color, 0) + 1
        anchors = []
        for y, x in component:
            if counts[int(grid[y, x])] == singleton:
                anchors.append((y, x))
        if len(anchors) != singleton:
            continue
        ay, ax = anchors[0]
        marker = int(grid[ay, ax])
        occupied = set(component)
        for target in np.argwhere(grid == marker):
            ty, tx = int(target[0]), int(target[1])
            if (ty, tx) in occupied:
                continue
            for y, x in component:
                yy, xx = ty + y - ay, tx + x - ax
                if 0 <= yy < height and 0 <= xx < width:
                    output[yy, xx] = grid[y, x]
    return output

def run(params, grid, demos):
    inset = int(round(params['geometry'][0]))
    minspan = int(round(params['geometry'][1]))
    coverage = float(params['geometry'][2])
    for value in params['colors']:
        color = int(round(value))
        points = np.argwhere(grid == color)
        if len(points) == 0:
            continue
        top = int(np.min(points[:, 0]))
        bottom = int(np.max(points[:, 0]))
        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1]))
        if bottom - top + 1 < minspan or right - left + 1 < minspan:
            continue
        border = np.concatenate((grid[top, left:right + 1], grid[bottom, left:right + 1], grid[top + 1:bottom, left], grid[top + 1:bottom, right]))
        if np.count_nonzero(border == color) >= coverage * len(border):
            if top + inset <= bottom - inset and left + inset <= right - inset:
                return grid[top + inset:bottom - inset + 1, left + inset:right - inset + 1].copy()
    return grid.copy()

def run(params, grid, demos):
