            valid = True
            for dr, dc in offsets:
                rr, cc = row + dr, col + dc
                if rr < 0 or rr >= height or cc < 0 or cc >= width:
                    continue
                value = grid[rr, cc]
                if value != marker and value != substrate:
                    valid = False
                    break
                cells.append((rr, cc))
                if value == marker:
                    markers.add((rr, cc))
            if valid and len(markers) >= required:
                candidates.append((cells, markers))
    for cells, markers in candidates:
        selected = True
        for other_cells, other_markers in candidates:
            if len(other_markers) > len(markers) and markers.intersection(other_markers):
                selected = False
                break
        if selected:
            for rr, cc in cells:
                if grid[rr, cc] == substrate:
                    out[rr, cc] = paint
    return out

