def run(params, grid, demos):
    bg, size, radius, legend, start, header = [int(round(v)) for v in params['geometry']]
    height, width = grid.shape
    if size <= 0 or radius < 0 or legend < 0 or legend >= height or header < 0 or header >= height or start <= 0 or start >= height:
        return grid.copy()
    mapping = {}
    for col in range(width):
        marker = int(grid[legend, col])
        if marker != bg:
            mapping[marker] = int(grid[header, col])
    body = grid[start:, :]
    out = np.full(body.shape, bg, dtype=int)
    for row, col in np.argwhere(body != bg):
        marker = int(body[row, col])
        if marker in mapping:
            top = int(row) - radius
            left = int(col) - radius
            bottom = min(body.shape[0], top + size)
            right = min(width, left + size)
            out[max(0, top):bottom, max(0, left):right] = mapping[marker]
    return out

