        return grid.copy()
    cr, cc = h // divisor, w // divisor
    if cr >= h or cc >= w:
        return grid.copy()
    color = int(grid[cr, cc])
    points = np.argwhere(grid == color)
    best_score = -1
    best_direction = None
    for direction in params['directions']:
        dr = int(round(direction[0]))
        dc = int(round(direction[1]))
        if abs(dr) != 1 or abs(dc) != 1:
            continue
        score = 0
        for point in points:
            if (int(point[0]) - cr) * dr > zero and (int(point[1]) - cc) * dc > zero:
                score += 1
        if score > best_score:
            best_score = score
            best_direction = (dr, dc)
    if best_direction is None:
        return grid.copy()
    out = np.full((h, w), bg, dtype=int)
    dr, dc = best_direction
