        r += dr
        c += dc
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    unit = int(round(params['rule'][1]))
    descending = bool(int(round(params['rule'][2])))
    align_right = bool(int(round(params['rule'][3])))
    offsets = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    h, w = grid.shape
    seen = set()
    counts = {}
    for r in range(h):
        for c in range(w):
            color = int(grid[r, c])
            if color == bg or (r, c) in seen:
                continue
            counts[color] = counts.get(color, 0) + unit
            seen.add((r, c))
            pending = [(r, c)]
            while pending:
                y, x = pending.pop()
                for dy, dx in offsets:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if (ny, nx) not in seen and int(grid[ny, nx]) == color:
                            seen.add((ny, nx))
                            pending.append((ny, nx))
    if not counts:
        return grid.copy()
    colors = list(counts)
    colors.sort(key=counts.get, reverse=descending)
    width = max(counts.values())
    if width <= 0:
        return grid.copy()
    result = np.full((len(colors), width), bg, dtype=int)
    for row, color in enumerate(colors):
        amount = counts[color]
        start = width - amount if align_right else 0
        result[row, start:start + amount] = color
    return result

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    sep = int(round(params['rule'][1]))
    step = int(round(params['rule'][2]))
    bottom = int(round(params['rule'][3]))
    if step == 0:
        return grid.copy()
    h, w = grid.shape
    cuts = []
    for c in range(w):
        if np.all(grid[:, c] == sep):
            cuts.append(c)
    if len(cuts) == 0:
        return grid.copy()
    panels = []
    start = 0
    for end in cuts + [w]:
        if end > start:
            panels.append(grid[:, start:end])
        start = end + 1
    pieces = []
    for panel in panels[::step]:
        rows = np.nonzero(np.any(panel != bg, axis=1))[0]
        if len(rows) > 0:
            pieces.append(panel[int(rows[0]):int(rows[-1]) + 1, :])
    if len(pieces) == 0:
        return np.full(panels[0].shape, bg, dtype=int)
    width = pieces[0].shape[1]
    for piece in pieces:
        if piece.shape[1] != width:
            return grid.copy()
    content = np.concatenate(pieces, axis=0)
    remaining = h - content.shape[0]
    if remaining < 0:
        return grid.copy()
    blank = np.full((remaining, width), bg, dtype=int)
    if bottom > 0:
        return np.concatenate([blank, content], axis=0)
    return np.concatenate([content, blank], axis=0)

def run(params, grid, demos):
    bg = int(round(params['settings'][0]))
