    for color in palette:
        if color == bg:
            continue
        rows = np.where(np.all(grid == color, axis=1))[0].tolist()
        cols = np.where(np.all(grid == color, axis=0))[0].tolist()
        if rows and cols:
            separator = color
            break
    if separator is None:
        return out
    for color in palette:
        if color == bg or color == separator:
            continue
        points = np.argwhere(grid == color).tolist()
        occupied = set()
        blockrows = set()
        blockcols = set()
        for r, c in points:
            br = sum(v < r for v in rows)
            bc = sum(v < c for v in cols)
            occupied.add((br, bc))
            blockrows.add(br)
            blockcols.add(bc)
        if len(blockrows) != pair or len(blockcols) != pair or len(occupied) != triple:
            continue
        if max(blockrows) - min(blockrows) != step or max(blockcols) - min(blockcols) != step:
            continue
        horizontal = rows[min(blockrows)]
        vertical = cols[min(blockcols)]
        for r, c in points:
            for rr in [r, pair * horizontal - r]:
                for cc in [c, pair * vertical - c]:
                    if 0 <= rr < grid.shape[0] and 0 <= cc < grid.shape[1]:
                        if out[rr, cc] == bg:
                            out[rr, cc] = color
    return out

