        return out
    for c in range(w):
        color = int(grid[top, c])
        if color == bg:
            continue
        stop = h - step
        target = c
        found = False
        for r in range(top + step, h, step):
            for side in (left, right):
                if int(grid[r, side]) == color:
                    stop = r
                    target = side
                    found = True
                    break
            if found:
                break
        for r in range(top, stop + step, step):
            if r < h:
                out[r, c] = color
        if found:
            for j in range(min(c, target), max(c, target) + step, step):
                if j < w:
                    out[stop, j] = color
    return out

