    candidates = [color for color in palette if color != background and int(np.count_nonzero(grid == color)) > threshold]
    result = grid.copy()
    if not candidates:
        return result
    block = max(candidates, key=lambda color: int(np.count_nonzero(grid == color)))
    height, width = grid.shape
    for position in np.argwhere((grid != background) & (grid != block)):
        row, col = int(position[0]), int(position[1])
