            if dr == 0 and dc == 0:
                continue
            r, c = row + dr, col + dc
            path = []
            while 0 <= r < height and 0 <= c < width:
                if grid[r, c] == block:
                    for pr, pc in path:
                        result[pr, pc] = color
                    break
                if grid[r, c] != background:
                    break
                path.append((r, c))
                r, c = r + dr, c + dc
