    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['directions']]
    h, w = grid.shape
    center = None
    candidates = np.argwhere((grid != bg) & (grid != yellow) & (grid != gray))
    for point in candidates:
        r, c = int(point[0]), int(point[1])
        valid = True
        for dr, dc in ring:
            rr, cc = r + dr, c + dc
            if rr < 0 or rr >= h or cc < 0 or cc >= w:
                valid = False
                break
            if grid[rr, cc] != yellow:
                valid = False
                break
        if valid:
            center = (r, c)
            break
    if center is None or radius <= 0:
        return grid.copy()
    r, c = center
    fill = int(grid[r, c])
    occupied = set((r + dr, c + dc) for dr, dc in ring)
    endpoint = None
    for point in np.argwhere(grid == yellow):
        position = (int(point[0]), int(point[1]))
        if position not in occupied:
            endpoint = position
            break
    start = None
    for point in np.argwhere(grid == fill):
        position = (int(point[0]), int(point[1]))
        if position != center:
            start = position
            break
    if endpoint is None or start is None:
        return grid.copy()
    cr = r + gain * (endpoint[0] - start[0])
    cc = c + gain * (endpoint[1] - start[1])
    out = np.full((h, w), fill, dtype=int)
    for dr, dc in ring:
        rr, col = cr + dr, cc + dc
        if 0 <= rr < h and 0 <= col < w:
            out[rr, col] = yellow
    for dr, dc in directions:
        for distance in range(radius, max(h, w)):
            rr, col = cr + distance * dr, cc + distance * dc
            if 0 <= rr < h and 0 <= col < w:
                out[rr, col] = yellow
    return out

