def run(params, grid, demos):
    bg = int(round(params['settings'][0]))
    step = int(round(params['settings'][1]))
    lines = int(round(params['settings'][2]))
    if step <= 0 or bg < 0 or bg >= len(np.bincount(grid.flatten())):
        return grid.copy()
    counts = np.bincount(grid.flatten())
    counts[bg] = 0
    wall = int(np.argmax(counts))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    seen = set()
    frames = []
    palette = {}
    for point in np.argwhere(grid == wall):
        start = (int(point[0]), int(point[1]))
        if start in seen:
            continue
        seen.add(start)
        queue = [start]
        component = []
        while queue:
            r, c = queue.pop()
            component.append((r, c))
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width:
                    if grid[nr, nc] == wall and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
        top = min(p[0] for p in component)
        bottom = max(p[0] for p in component)
        left = min(p[1] for p in component)
        right = max(p[1] for p in component)
        rows = []
        cols = []
        for r in range(top, bottom + step):
            if np.all(grid[r, left:right + step] == wall):
                rows.append(r)
        for c in range(left, right + step):
            if np.all(grid[top:bottom + step, c] == wall):
                cols.append(c)
        if len(rows) != lines or len(cols) != lines:
            continue
        frames.append((rows, cols))
        for i in range(len(rows) - step):
            for j in range(len(cols) - step):
                cell = grid[rows[i] + step:rows[i + step], cols[j] + step:cols[j + step]]
                colors = np.unique(cell)
                for color in colors:
                    if color != bg and color != wall:
                        palette[(i, j)] = int(color)
    result = grid.copy()
    for rows, cols in frames:
        for i in range(len(rows) - step):
            for j in range(len(cols) - step):
                if (i, j) in palette:
                    result[rows[i] + step:rows[i + step], cols[j] + step:cols[j + step]] = palette[(i, j)]
    return result

