    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    height, width = grid.shape
    seen = set()
    components = []
    for r in range(height):
        for c in range(width):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            pending = [(r, c)]
            while pending:
                x, y = pending.pop()
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < height and 0 <= ny < width:
                        if grid[nx, ny] != bg and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            cells.append((nx, ny))
                            pending.append((nx, ny))
            components.append(cells)
    templates = [cells for cells in components if all(grid[r, c] != marker for r, c in cells)]
    if len(templates) != 1:
        return grid.copy()
    template = templates[0]
    top = min(r for r, c in template)
    left = min(c for r, c in template)
    pattern = {(r - top, c - left): int(grid[r, c]) for r, c in template}
    result = grid.copy()
    for r, c in template:
        result[r, c] = bg
    for cells in components:
        if not all(grid[r, c] == marker for r, c in cells):
            continue
        row = min(r for r, c in cells)
        col = min(c for r, c in cells)
        support = set((r - row, c - col) for r, c in cells)
        if support == set(pattern):
            for r, c in cells:
                result[r, c] = pattern[(r - row, c - col)]
    return result

