    for row in range(height):
        values = [int(value) for value in np.unique(grid[row]) if int(value) != background and int(value) != axis and int(value) != separator]
        if len(values) > 0:
            seeds.append(row)
            colors.append(values[0])
    if len(seeds) == 0:
        return grid.copy()
    result = np.full(grid.shape, separator, dtype=int)
    for row in range(height):
        distances = [abs(row - seed) for seed in seeds]
        nearest = min(distances)
        candidates = [colors[index] for index in range(len(seeds)) if distances[index] == nearest]
        if len(set(candidates)) == 1:
