    offsets = []
    for pair in params['offsets']:
        offsets.append((int(round(pair[0])), int(round(pair[1]))))
    separator = bg
    for row in grid:
        if row[0] != bg and np.all(row == row[0]):
            separator = int(row[0])
            break
    if separator == bg:
        return out
    rows = []
    previous = -step
    for r in range(grid.shape[0]):
        if not np.all(grid[r, :] == separator):
            if not rows or r != previous + step:
                rows.append([])
            rows[-1].append(r)
            previous = r
    cols = []
    previous = -step
    for c in range(grid.shape[1]):
        if not np.all(grid[:, c] == separator):
            if not cols or c != previous + step:
                cols.append([])
            cols[-1].append(c)
            previous = c
    if not rows or not cols:
        return out
    cells = np.array([[grid[rr[0], cc[0]] for cc in cols] for rr in rows])
    best = -step
    center = None
    for r in range(len(rows)):
        for c in range(len(cols)):
            if cells[r, c] == bg:
                continue
            score = 0
            for dr, dc in offsets:
                if dr == 0 and dc == 0:
                    continue
                nr = r + dr
                nc = c + dc
                if 0 <= nr < len(rows) and 0 <= nc < len(cols):
                    if cells[nr, nc] != bg:
                        score += step
            if score > best:
                best = score
                center = (r, c)
    if center is None or best <= 0:
        return out
    cr, cc = center
    marker = int(cells[cr, cc])
    pattern = []
    for dr, dc in offsets:
        nr = cr + dr
        nc = cc + dc
        if 0 <= nr < len(rows) and 0 <= nc < len(cols):
