def components(mask, steps):
    seen = set()
    groups = []
    h, w = mask.shape
    for r in range(h):
        for c in range(w):
            if mask[r, c] and (r, c) not in seen:
                group = [(r, c)]
                seen.add((r, c))
                queue = [(r, c)]
                while queue:
                    y, x = queue.pop()
                    for dy, dx in steps:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            queue.append((ny, nx))
                            group.append((ny, nx))
                groups.append(group)
    return groups
