    steps = [(int(round(p[0])), int(round(p[1]))) for p in params['steps']]
    edges = [int(round(v)) for v in params['edges']]
    out = grid.copy()
    points = np.argwhere(grid == wall)
    if len(points) == 0:
        return out
    top = int(np.min(points[:, 0]))
    bottom = int(np.max(points[:, 0]))
    left = int(np.min(points[:, 1]))
    right = int(np.max(points[:, 1]))
    region = grid[top:bottom + 1, left:right + 1]
    h, w = region.shape
    holes = []
    for group in components(region == bg, steps):
        blocked = False
        for r, c in group:
            if (edges[0] and r == 0) or (edges[1] and r == h - 1) or (edges[2] and c == 0) or (edges[3] and c == w - 1):
                blocked = True
        if not blocked:
            anchor_r, anchor_c = group[0]
            width = max(c for r, c in group) - min(c for r, c in group) + 1
            holes.append((width, [(r - anchor_r, c - anchor_c) for r, c in group]))
    for group in components(grid == object_color, steps):
        cells = set(group)
        object_width = max(c for r, c in group) - min(c for r, c in group) + 1
        matched = False
        for width, hole in holes:
            if width <= narrow and object_width != width:
                continue
            for r, c in group:
                if all((r + dy, c + dx) in cells for dy, dx in hole):
                    matched = True
                    break
            if matched:
                break
        if matched:
            for r, c in group:
                out[r, c] = result_color
    return out

def run(params, grid, demos):
