def run(params, grid, demos):
    step = int(round(params['geometry'][0]))
    minimum = int(round(params['geometry'][1]))
    fraction = float(params['uniformity'][0])
    blank = int(round(params['fallback'][0]))
    if step <= 0:
        return np.array([[blank]], dtype=int)
    height, width = grid.shape
    rows = [-step]
    cols = [-step]
    for r in range(height):
        if np.all(grid[r, :] == grid[r, 0]):
            rows.append(r)
    for c in range(width):
        if np.all(grid[:, c] == grid[0, c]):
            cols.append(c)
    rows.append(height)
    cols.append(width)
    rowspans = []
    colspans = []
    for a, b in zip(rows, rows[1:]):
        if b - a - step >= minimum:
            rowspans.append((a + step, b))
    for a, b in zip(cols, cols[1:]):
        if b - a - step >= minimum:
            colspans.append((a + step, b))
    cells = []
    for i, (a, b) in enumerate(rowspans):
        for j, (c, d) in enumerate(colspans):
            block = grid[a:b, c:d]
            color = int(block[0, 0])
            if np.count_nonzero(block == color) == block.size * fraction:
                cells.append((i, j, color))
    if not cells:
        return np.array([[blank]], dtype=int)
    top = min(cell[0] for cell in cells)
    bottom = max(cell[0] for cell in cells)
    left = min(cell[1] for cell in cells)
    right = max(cell[1] for cell in cells)
    output = np.full((bottom - top + step, right - left + step), blank, dtype=int)
    for i, j, color in cells:
        output[i - top, j - left] = color
    return output

