        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1]))
        vertical = 0
        horizontal = 0
        for row in [top, bottom]:
            for column in [left, right]:
                if int(grid[row, column]) == marker:
                    vertical = negative if row == top else positive
                    horizontal = negative if column == left else positive
        for row in range(top, bottom + 1):
            for column in range(left, right + 1):
                target_row = row + vertical
                target_column = column + horizontal
                if 0 <= target_row < height and 0 <= target_column < width:
