        color = int(grid[row, col])
        if row < height * midpoint:
            row_start, row_end = start, row + step
        else:
            row_start, row_end = row, height
        if col < width * midpoint:
            col_start, col_end = start, col + step
        else:
            col_start, col_end = col, width
        result[row_start:row_end, col_start:col_end] = color
    return result

def run(params, grid, demos):
    blue = int(round(params['rule'][0]))
    red = int(round(params['rule'][1]))
    dr = int(round(params['rule'][2]))
    dc = int(round(params['rule'][3]))
    length_gain = int(round(params['rule'][4]))
    mark_gain = int(round(params['rule'][5]))
    out = grid.copy()
    h, w = grid.shape
    if dr == 0 and dc == 0:
        return out
    rods = []
    source = None
    for r in range(h):
        for c in range(w):
            if grid[r, c] != blue and grid[r, c] != red:
                continue
            pr, pc = r - dr, c - dc
            if 0 <= pr < h and 0 <= pc < w:
                if grid[pr, pc] == blue or grid[pr, pc] == red:
                    continue
            cells = []
            rr, cc = r, c
            marked = 0
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr, cc] != blue and grid[rr, cc] != red:
                    break
                cells.append((rr, cc))
                if grid[rr, cc] == red:
                    marked += 1
                rr += dr
                cc += dc
            rods.append(cells)
            if marked > 0:
                source = (cells, marked, grid[r, c] == red)
    if source is None:
        return out
    cells, marked, from_start = source
    for r, c in cells:
        out[r, c] = blue
    for target in rods:
        if len(target) == len(cells) + length_gain:
            count = marked + mark_gain
            if count < 0 or count > len(target):
                continue
            chosen = target[:count] if from_start else target[len(target) - count:]
            for r, c in chosen:
                out[r, c] = red
    return out

def run(params, grid, demos):
