    for point in points:
        row = int(point[0])
        col = int(point[1])
        for row_weight in params['directions']:
            row_sign = int(round(row_weight))
            target_row = row_sign * row + (unit - row_sign) * row_sum // divisor
            for col_weight in params['directions']:
                col_sign = int(round(col_weight))
                target_col = col_sign * col + (unit - col_sign) * col_sum // divisor
                if 0 <= target_row < grid.shape[0] and 0 <= target_col < grid.shape[1]:
