        return out
    height, width = grid.shape
    marker = None
    center = None
    for color in np.unique(grid):
        if color == bg:
            continue
        points = np.argwhere(grid == color)
        if len(points) != len(offsets):
            continue
        cr = int(round((int(np.min(points[:, 0])) + int(np.max(points[:, 0]))) / divisor))
        cc = int(round((int(np.min(points[:, 1])) + int(np.max(points[:, 1]))) / divisor))
        matches = True
        for dr, dc in offsets:
            rr, rc = cr + dr, cc + dc
            if not (0 <= rr < height and 0 <= rc < width):
                matches = False
                break
            if grid[rr, rc] != color:
                matches = False
                break
        if matches:
            marker = color
            center = (cr, cc)
            break
    if center is None:
        return out
    cr, cc = center
    for r, c in np.argwhere(np.logical_and(grid != bg, grid != marker)):
        for sr in signs:
            for sc in signs:
                rr = cr + sr * (int(r) - cr)
                rc = cc + sc * (int(c) - cc)
                if 0 <= rr < height and 0 <= rc < width:
                    out[rr, rc] = grid[r, c]
    return out

def run(params, grid, demos):
    bg = int(round(params['settings'][0]))
    limit = int(round(params['settings'][1]))
    directions = [(int(round(pair[0])), int(round(pair[1]))) for pair in params['directions']]
    h, w = grid.shape
    seen = np.zeros((h, w), dtype=bool)
    out = np.full((h, w), bg, dtype=int)
    objects = []
    for r in range(h):
        for c in range(w):
            if seen[r, c] or grid[r, c] == bg:
                continue
            color = int(grid[r, c])
            cells = [(r, c)]
            seen[r, c] = True
            pos = 0
            while pos < len(cells):
                y, x = cells[pos]
                pos += 1
                for dy, dx in directions:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if not seen[yy, xx] and grid[yy, xx] == color:
                            seen[yy, xx] = True
                            cells.append((yy, xx))
            if len(cells) >= limit:
                objects.append((color, cells))
    for color, cells in objects:
        wall = np.zeros((h, w), dtype=bool)
        for y, x in cells:
            wall[y, x] = True
            out[y, x] = color
        exterior = np.zeros((h, w), dtype=bool)
        queue = []
        for y in range(h):
            for x in range(w):
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    if not wall[y, x]:
                        exterior[y, x] = True
                        queue.append((y, x))
        pos = 0
        while pos < len(queue):
            y, x = queue[pos]
            pos += 1
            for dy, dx in directions:
                yy, xx = y + dy, x + dx
                if 0 <= yy < h and 0 <= xx < w:
                    if not wall[yy, xx] and not exterior[yy, xx]:
                        exterior[yy, xx] = True
                        queue.append((yy, xx))
        inside = np.logical_and(np.logical_not(wall), np.logical_not(exterior))
        votes = grid[np.logical_and(inside, grid != bg)]
        if votes.size:
            colors, counts = np.unique(votes, return_counts=True)
            winner = int(colors[np.argmax(counts)])
            out[inside] = winner
    return out

def run(params, grid, demos):
