    offsets = params['neighbors']
    while pending:
        row, col = pending.pop()
        for offset in offsets:
            next_row = row + int(round(offset[0]))
            next_col = col + int(round(offset[1]))
            if 0 <= next_row < height and 0 <= next_col < width:
                point = (next_row, next_col)
                if point not in visited and grid[next_row, next_col] != background:
                    visited.add(point)
                    pending.append(point)
    rows = [point[0] for point in visited]
    cols = [point[1] for point in visited]
    counts = {}
    for row, col in visited:
        color = int(grid[row, col])
        if color != marker and color != background:
            counts[color] = counts.get(color, 0) + 1
    if not counts:
        return grid.copy()
    replacement = max(counts, key=counts.get)
    result = grid[min(rows):max(rows) + 1, min(cols):max(cols) + 1].copy()
    result[result == marker] = replacement
    return result

