    zero = int(round(params['geometry'][1]))
    if bg == body or unit != 1 or zero != 0:
        return grid.copy()
    steps = []
    for pair in params['neighbors']:
        steps.append((int(round(pair[0])), int(round(pair[1]))))
    remaining = set()
    for p in np.argwhere(grid == body):
        remaining.add((int(p[0]), int(p[1])))
    markers = []
    for p in np.argwhere((grid != bg) & (grid != body)):
        markers.append((int(p[0]), int(p[1]), int(grid[p[0], p[1]])))
    if not remaining or not markers:
        return grid.copy()
    objects = []
    while remaining:
        seed = remaining.pop()
        pending = [seed]
        points = [seed]
        while pending:
            r, c = pending.pop()
            for dr, dc in steps:
                q = (r + dr, c + dc)
                if q in remaining:
                    remaining.remove(q)
                    pending.append(q)
                    points.append(q)
        rows = [p[0] for p in points]
        cols = [p[1] for p in points]
        objects.append((min(rows), max(rows), min(cols), max(cols), points))
    row_centers = [o[0] + o[1] for o in objects]
    col_centers = [o[2] + o[3] for o in objects]
    vertical = max(row_centers) - min(row_centers) >= max(col_centers) - min(col_centers)
    axis = int(round(params['axes'][int(vertical)]))
    if axis != zero and axis != unit:
        return grid.copy()
    if axis == zero:
        objects.sort(key=lambda o: (o[0], o[2]))
    else:
        objects.sort(key=lambda o: (o[2], o[0]))
    pieces = []
    for top, bottom, left, right, points in objects:
        best = None
        color = bg
        for r, c, value in markers:
            distance = max(top - r, r - bottom, zero) + max(left - c, c - right, zero)
            if best is None or distance < best:
                best = distance
                color = value
        piece = np.full((bottom - top + unit, right - left + unit), bg, dtype=int)
        for r, c in points:
            piece[r - top, c - left] = color
        pieces.append(piece)
    return np.concatenate(pieces, axis=axis)

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    endpoint_degree = int(round(params['rule'][1]))
    reverse_step = int(round(params['rule'][2]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    result = grid.copy()
    if reverse_step == 0:
        return result
    cells = set()
    for position in np.argwhere(grid != background):
        cells.add((int(position[0]), int(position[1])))
    endpoints = []
    for cell in sorted(cells):
        degree = 0
        for dr, dc in directions:
            if (cell[0] + dr, cell[1] + dc) in cells:
                degree += 1
        if degree == endpoint_degree:
            endpoints.append(cell)
    if not endpoints:
        return result
    current = endpoints[0]
    visited = set()
    path = []
    while current not in visited:
        visited.add(current)
        path.append(current)
        candidates = []
        for dr, dc in directions:
            neighbor = (current[0] + dr, current[1] + dc)
            if neighbor in cells and neighbor not in visited:
                candidates.append(neighbor)
        if not candidates:
            break
        current = candidates[0]
    values = [int(grid[r, c]) for r, c in path]
    values = values[::reverse_step]
    for cell, value in zip(path, values):
        result[cell[0], cell[1]] = value
    return result

def run(params, grid, demos):
