def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    colors = [int(round(params['rule'][1])), int(round(params['rule'][2]))]
    crossing = int(round(params['rule'][3]))
    step = int(round(params['rule'][4]))
    directions = [int(round(params['rule'][5])), int(round(params['rule'][6]))]
    out = np.full(grid.shape, bg, dtype=int)
    zero = step - step
    if step <= zero:
        return out
    for color in colors:
        points = np.argwhere(grid == color)
        if len(points) == zero:
            continue
        top = int(np.min(points[:, 0]))
        bottom = int(np.max(points[:, 0]))
        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1]))
        length = bottom - top + step
        if length <= zero:
            continue
        for row in range(grid.shape[0]):
            distance = max(top - row, row - bottom, zero)
            shift = ((distance + length - step) // length) * step
            for anchor, direction in zip([left, right], directions):
                col = anchor + direction * shift
                if zero <= col < grid.shape[1]:
                    if out[row, col] == bg or out[row, col] == color:
                        out[row, col] = color
                    else:
                        out[row, col] = crossing
    return out

def run(params, grid, demos):
    bg = int(round(params['config'][0]))
    base = int(round(params['config'][1]))
    ink = int(round(params['config'][2]))
    unit = int(round(params['config'][3]))
    expected = int(round(params['config'][4]))
    if unit <= 0:
        return grid.copy()
    directions = []
    for pair in params['neighbors']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    seen = set()
    boxes = []
    for r in range(height):
        for c in range(width):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            queue = [(r, c)]
            seen.add((r, c))
            pos = 0
            while pos < len(queue):
                y, x = queue[pos]
                pos += unit
                for dy, dx in directions:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < height and 0 <= nx < width:
                        if grid[ny, nx] != bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            queue.append((ny, nx))
            rows = [p[0] for p in queue]
            cols = [p[1] for p in queue]
            boxes.append(grid[min(rows):max(rows) + unit, min(cols):max(cols) + unit].copy())
    if len(boxes) != expected:
        return grid.copy()
    motif = None
    canvas = None
    layout = None
    for box in boxes:
        if np.any(box == base):
            motif = box
        elif np.all(box == box[0, 0]):
            if canvas is None or box.shape[0] * box.shape[1] > canvas.shape[0] * canvas.shape[1]:
                canvas = box
    if motif is None or canvas is None:
        return grid.copy()
    for box in boxes:
        if box is not motif and box is not canvas:
            layout = box
    if layout is None:
        return grid.copy()
    mh, mw = motif.shape
    ch, cw = canvas.shape
    if ch % mh != 0 or cw % mw != 0:
        return grid.copy()
    nr, nc = ch // mh, cw // mw
    lh, lw = layout.shape
    if nr <= 0 or nc <= 0 or lh % nr != 0 or lw % nc != 0:
        return grid.copy()
    sy, sx = lh // nr, lw // nc
    out = canvas.copy()
    fill = int(canvas[0, 0])
    stamp = np.where(motif == ink, ink, fill)
    for r in range(nr):
        for c in range(nc):
            if layout[r * sy, c * sx] == ink:
                out[r * mh:(r + unit) * mh, c * mw:(c + unit) * mw] = stamp
    return out

