def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    minimum_length = int(round(params['rule'][1]))
    step = int(round(params['rule'][2]))
    out = grid.copy()
    if step <= 0:
        return np.full(grid.shape, bg, dtype=int)
    height, width = grid.shape
    templates = []
    covered = set()
    for r in range(height):
        c = 0
        while c < width:
            if int(grid[r, c]) == bg:
                c += step
                continue
            start = c
            sequence = []
            positions = []
            while c < width and int(grid[r, c]) != bg:
                sequence.append(int(grid[r, c]))
                positions.append((r, c))
                c += step
            if len(sequence) >= minimum_length:
                templates.append(sequence)
                covered.update(positions)
    for r in range(height):
        for c in range(width):
            color = int(grid[r, c])
            if color == bg or (r, c) in covered:
                continue
            for sequence in templates:
                if color in sequence:
                    anchor = sequence.index(color)
                    for j in range(len(sequence)):
                        target = c + (j - anchor) * step
                        if 0 <= target < width:
                            out[r, target] = sequence[j]
                    break
    return out

def run(params, grid, demos):
    bg = int(round(params['settings'][0]))
    unit = int(round(params['settings'][1]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    out = grid.copy()
    height, width = grid.shape
    remaining = set()
    for point in np.argwhere(grid != bg):
        remaining.add((int(point[0]), int(point[1])))
    components = []
    while remaining:
        start = remaining.pop()
        component = [start]
        queue = [start]
        while queue:
            r, c = queue.pop()
            for dr, dc in directions:
                neighbor = (r + dr, c + dc)
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    component.append(neighbor)
                    queue.append(neighbor)
        components.append(component)
    template = None
    for component in components:
        rows = [point[0] for point in component]
        cols = [point[1] for point in component]
        area = (max(rows) - min(rows) + unit) * (max(cols) - min(cols) + unit)
        if len(component) != area:
            if template is None or len(component) > len(template):
                template = component
    if template is None or unit <= 0:
        return out
    shared = set(int(grid[r, c]) for r, c in template)
    for component in components:
        shared = shared.intersection(set(int(grid[r, c]) for r, c in component))
    if len(shared) != unit:
        return out
    marker = shared.pop()
    anchors = [(r, c) for r, c in template if int(grid[r, c]) == marker]
    anchor_r = min(point[0] for point in anchors)
    anchor_c = min(point[1] for point in anchors)
    for component in components:
        if component is template:
            continue
        markers = [(r, c) for r, c in component if int(grid[r, c]) == marker]
        paints = [int(grid[r, c]) for r, c in component if int(grid[r, c]) != marker]
        if not markers or not paints:
            continue
        origin_r = min(point[0] for point in markers)
        origin_c = min(point[1] for point in markers)
        scale_r = max(point[0] for point in markers) - origin_r + unit
        scale_c = max(point[1] for point in markers) - origin_c + unit
        paint = paints[0]
        for r, c in template:
            if int(grid[r, c]) == marker:
                continue
            top = origin_r + (r - anchor_r) * scale_r
            left = origin_c + (c - anchor_c) * scale_c
            for rr in range(max(0, top), min(height, top + scale_r)):
                for cc in range(max(0, left), min(width, left + scale_c)):
                    out[rr, cc] = paint
    return out

