    cuts = []
    for c in range(grid.shape[1]):
        if np.all(grid[:, c] == sep):
            cuts.append(c)
    panels = []
    start = 0
    for c in cuts:
        if c > start:
            panels.append(grid[:, start:c])
        start = c + 1
    if start < grid.shape[1]:
        panels.append(grid[:, start:])
    if len(panels) == 0:
        return grid.copy()
    out = np.full(panels[0].shape, bg, dtype=int)
    for p in range(min(len(panels), len(params['ranks']))):
        panel = panels[p]
        seen = set()
        objects = []
        for r in range(panel.shape[0]):
            for c in range(panel.shape[1]):
                if (r, c) in seen or int(panel[r, c]) == bg:
                    continue
                color = int(panel[r, c])
                points = [(r, c)]
                seen.add((r, c))
                cursor = 0
                while cursor < len(points):
                    y, x = points[cursor]
                    cursor += 1
                    for dy, dx in steps:
                        yy, xx = y + dy, x + dx
                        if yy >= 0 and yy < panel.shape[0] and xx >= 0 and xx < panel.shape[1]:
                            if (yy, xx) not in seen and int(panel[yy, xx]) == color:
                                seen.add((yy, xx))
                                points.append((yy, xx))
                left = min(x for y, x in points)
                top = min(y for y, x in points)
                objects.append((left, top, color, points))
        objects.sort()
        rank = int(round(params['ranks'][p]))
        if rank >= 0 and rank < len(objects):
            for y, x in objects[rank][3]:
                if y < out.shape[0] and x < out.shape[1]:
