    if len(rows) != 1:
        return grid.copy()
    split = int(rows[0])
    upper = grid[:split, :]
    lower = grid[split + gap:, :]
    if upper.shape != lower.shape:
        return grid.copy()
    empty = np.logical_and(upper == background, lower == background)
    return np.where(empty, marker, background).astype(int)

def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    small_color = int(round(params['colors'][1]))
    large_color = int(round(params['colors'][2]))
    directions = [(int(round(pair[0])), int(round(pair[1]))) for pair in params['directions']]
    height, width = grid.shape
    seen = set()
    components = []
    for row in range(height):
        for col in range(width):
            if grid[row, col] != background or (row, col) in seen:
                continue
            component = [(row, col)]
            seen.add((row, col))
            position = 0
            while position < len(component):
                current_row, current_col = component[position]
                position += 1
                for dr, dc in directions:
                    next_row = current_row + dr
                    next_col = current_col + dc
                    if 0 <= next_row < height and 0 <= next_col < width:
                        if grid[next_row, next_col] == background and (next_row, next_col) not in seen:
                            seen.add((next_row, next_col))
                            component.append((next_row, next_col))
            components.append(component)
    result = grid.copy()
    if len(components) == 0:
        return result
    sizes = np.array([len(component) for component in components])
    smallest = np.min(sizes)
    largest = np.max(sizes)
    for component in components:
        if len(component) == smallest:
            for row, col in component:
                result[row, col] = small_color
        elif len(component) == largest:
            for row, col in component:
                result[row, col] = large_color
    return result

def spans(mask):
    result = []
    start = None
    for i in range(len(mask)):
        if not mask[i]:
            if start is None:
                start = i
        elif start is not None:
            result.append((start, i))
            start = None
    if start is not None:
        result.append((start, len(mask)))
    return result

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    noise = int(round(params['rule'][1]))
    diversity = int(round(params['rule'][2]))
    evidence = int(round(params['rule'][3]))
    separator = np.logical_or(grid == background, grid == noise)
    rows = spans(np.all(separator, axis=1))
    cols = spans(np.all(separator, axis=0))
    template = None
    for top, bottom in rows:
        for left, right in cols:
            block = grid[top:bottom, left:right]
            if np.any(block == noise) or np.any(block == background):
                continue
            if len(np.unique(block)) >= diversity:
                template = block.copy()
                break
        if template is not None:
            break
    if template is None:
        return grid.copy()
    colors, counts = np.unique(template, return_counts=True)
    main = int(colors[np.argmax(counts)])
    result = np.full(grid.shape, background, dtype=int)
    for top, bottom in rows:
        for left, right in cols:
            block = grid[top:bottom, left:right]
            if np.count_nonzero(block == main) >= evidence:
                result[top:bottom, left:right] = main
            elif block.shape == template.shape:
                result[top:bottom, left:right] = template
            else:
                return grid.copy()
    return result

