    edges = np.zeros((len(colours), len(colours)))
    for a in range(len(colours)):
        for b in range(len(colours)):
            if a != b:
                overlap = masks[a] & masks[b]
                evidence = np.count_nonzero(overlap & (grid == colours[b]))
                if strength * evidence > threshold:
                    edges[a, b] = strength
    remaining = list(range(len(colours)))
    ordered = []
    while remaining:
        chosen = remaining[0]
        for candidate in remaining:
            blocked = False
            for predecessor in remaining:
                if edges[predecessor, candidate] > threshold:
                    blocked = True
                    break
            if not blocked:
                chosen = candidate
                break
        ordered.append(colours[chosen])
        remaining.remove(chosen)
    return np.array(ordered, dtype=int).reshape((-1, 1))

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    one = int(round(params['rule'][1]))
    minimum_size = int(round(params['rule'][2]))
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    h, w = grid.shape
    out = grid.copy()
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            color = int(grid[r, c])
            cells = [(r, c)]
            seen.add((r, c))
            for a, b in cells:
                for dr, dc in directions:
                    x, y = a + dr, b + dc
                    if 0 <= x < h and 0 <= y < w and (x, y) not in seen and grid[x, y] == color:
                        seen.add((x, y))
                        cells.append((x, y))
            components.append((color, cells))
    markers = {}
    for color, cells in components:
        if len(cells) == one:
            markers[cells[0]] = color
    for color, cells in components:
        if len(cells) < minimum_size:
            continue
        occupied = set(cells)
        endpoints = []
        for a, b in cells:
            adjacent = []
            for dr, dc in directions:
                p = (a + dr, b + dc)
                if p in occupied:
                    adjacent.append(p)
            if len(adjacent) == one and adjacent:
                endpoints.append(((a, b), adjacent[0]))
        for endpoint, neighbor in endpoints:
            dr = endpoint[0] - neighbor[0]
            dc = endpoint[1] - neighbor[1]
            x, y = endpoint[0] + dr, endpoint[1] + dc
            extension = []
            while 0 <= x < h and 0 <= y < w and grid[x, y] == bg:
                extension.append((x, y))
                x, y = x + dr, y + dc
            if (x, y) not in markers:
                continue
            replacement = markers[(x, y)]
            for a, b in extension:
                out[a, b] = color
            opposite = [p for p, q in endpoints if p != endpoint]
            if not opposite:
                continue
            current = opposite[0]
            walked = set()
            for unused in extension:
                out[current[0], current[1]] = replacement
                walked.add(current)
                following = []
                for ar, ac in directions:
                    p = (current[0] + ar, current[1] + ac)
                    if p in occupied and p not in walked:
                        following.append(p)
                if not following:
                    break
                current = following[0]
            break
    return out

def run(params, grid, demos):
    background = int(round(params['settings'][0]))
    wall = int(round(params['settings'][1]))
    unit = int(round(params['settings'][2]))
    if background == wall or unit <= 0:
        return grid.copy()
    height, width = grid.shape
    edges = [grid[0, :], grid[height - unit, :], grid[:, 0], grid[:, width - unit]]
    direction = None
    for index, edge in enumerate(edges):
        if np.all(edge == wall):
            direction = params['directions'][index]
            break
    if direction is None:
        return grid.copy()
    dr = int(round(direction[0]))
    dc = int(round(direction[1]))
    if abs(dr) + abs(dc) != unit:
        return grid.copy()
    neighbours = []
    for offset in params['neighbours']:
        neighbours.append((int(round(offset[0])), int(round(offset[1]))))
    seen = set()
    objects = []
    for row in range(height):
        for col in range(width):
            colour = int(grid[row, col])
            if colour == background or colour == wall or (row, col) in seen:
                continue
            cells = [(row, col)]
            seen.add((row, col))
            cursor = 0
            while cursor < len(cells):
                r, c = cells[cursor]
                cursor += unit
                for nr, nc in neighbours:
                    rr, cc = r + nr, c + nc
                    if 0 <= rr < height and 0 <= cc < width and (rr, cc) not in seen and int(grid[rr, cc]) == colour:
                        seen.add((rr, cc))
                        cells.append((rr, cc))
            objects.append((colour, cells))
    objects.sort(key=lambda item: max(r * dr + c * dc for r, c in item[1]), reverse=True)
    result = np.full(grid.shape, background, dtype=grid.dtype)
    result[grid == wall] = wall
    for colour, cells in objects:
        for step in range(height + width):
            shifted = [(r + dr, c + dc) for r, c in cells]
            valid = True
            for r, c in shifted:
                if r < 0 or r >= height or c < 0 or c >= width:
                    valid = False
                    break
                if int(result[r, c]) != background:
                    valid = False
                    break
            if not valid:
                break
            cells = shifted
        for r, c in cells:
            result[r, c] = colour
    return result

