    if divisor <= 0:
        return grid.copy()
    points = np.argwhere(grid != background)
    if len(points) == 0:
        return grid.copy()
    top = int(np.min(points[:, 0]))
    bottom = int(np.max(points[:, 0])) + 1
    left = int(np.min(points[:, 1]))
    right = int(np.max(points[:, 1])) + 1
    height = (bottom - top) // divisor
    width = (right - left) // divisor
    if height <= 0 or width <= 0:
        return grid.copy()
    top = top + (row_part % divisor) * height
    left = left + (col_part % divisor) * width
    return grid[top:top + height, left:left + width].copy()

