    axis = int(round(params['reflection_axis'][0]))
    marks = np.argwhere(grid == marker)
    if len(marks) != corners or len(marks) == 0 or inset <= 0 or axis < 0 or axis >= grid.ndim:
        return grid.copy()
    top = int(np.min(marks[:, 0]))
    bottom = int(np.max(marks[:, 0]))
    left = int(np.min(marks[:, 1]))
    right = int(np.max(marks[:, 1]))
    if top + inset >= bottom or left + inset >= right:
        return grid.copy()
    left_color = int(grid[top + inset, left])
    right_color = int(grid[top + inset, right])
    points = []
    for point in np.argwhere(np.logical_and(grid != bg, grid != marker)):
        r = int(point[0])
        c = int(point[1])
        if r < top or r > bottom or c < left or c > right:
            points.append([r, c])
    if len(points) == 0:
        return grid.copy()
    positions = np.array(points)
    r0 = int(np.min(positions[:, 0]))
    r1 = int(np.max(positions[:, 0]))
    c0 = int(np.min(positions[:, 1]))
    c1 = int(np.max(positions[:, 1]))
    pattern = grid[r0:r1 + inset, c0:c1 + inset].copy()
    lp = np.argwhere(pattern == left_color)
    rp = np.argwhere(pattern == right_color)
    if len(lp) == 0 or len(rp) == 0:
        return grid.copy()
    if np.min(lp[:, axis]) > np.min(rp[:, axis]):
        pattern = np.flip(pattern, axis=axis)
    out = grid[top:bottom + inset, left:right + inset].copy()
    h, w = pattern.shape
    if h > out.shape[0] - inset - inset or w > out.shape[1] - inset - inset:
        return grid.copy()
    out[inset:inset + h, inset:inset + w] = pattern
    return out

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    fg = int(round(params['colors'][1]))
    wall = int(round(params['colors'][2]))
    step = int(round(params['motion'][0]))
    wide = int(round(params['motion'][1]))
    gap = int(round(params['motion'][2]))
    height, width = grid.shape
    barriers = [r for r in range(height) if np.all(grid[r] == wall)]
    if len(barriers) != 1 or bg == fg or step <= 0 or wide <= 1:
        return grid.copy()
    barrier = barriers[0]
    out = grid.copy()
    out[grid == fg] = bg
    remaining = set((int(p[0]), int(p[1])) for p in np.argwhere(grid == fg))
    directions = [(int(round(params['neighbors'][i][0])), int(round(params['neighbors'][i][1]))) for i in range(len(params['neighbors']))]
    while remaining:
        seed = remaining.pop()
        component = [seed]
        queue = [seed]
        while queue:
            r, c = queue.pop()
            for dr, dc in directions:
                neighbor = (r + dr, c + dc)
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    component.append(neighbor)
                    queue.append(neighbor)
        counts = {}
        for r, c in component:
            counts[r] = counts.get(r, 0) + 1
        broad_rows = [r for r in counts if counts[r] >= wide]
        if broad_rows:
            shift = barrier - gap - max(broad_rows)
        else:
            shift = height - gap - max(r for r, c in component)
        shift = max(0, shift)
        shift = (shift // step) * step
        for r, c in component:
            if r < barrier and r + shift >= barrier:
                out[barrier, c] = bg
        for r, c in component:
            target = r + shift
            if 0 <= target < height:
                out[target, c] = fg
    return out

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    anchor_r = int(round(params['anchor'][0]))
    anchor_c = int(round(params['anchor'][1]))
    gap = int(round(params['gravity'][0]))
    step = int(round(params['gravity'][1]))
    h, w = grid.shape
    terrain = int(grid[anchor_r % h, anchor_c % w])
    if step <= 0 or gap < 0:
        return grid.copy()
    directions = []
    for pair in params['neighbors']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r, c] == bg or grid[r, c] == terrain:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            cursor = 0
            while cursor < len(cells):
                y, x = cells[cursor]
                cursor += 1
                for dy, dx in directions:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen:
                        if grid[ny, nx] != bg and grid[ny, nx] != terrain:
                            seen.add((ny, nx))
                            cells.append((ny, nx))
            components.append(cells)
    out = grid.copy()
    for cells in components:
        for r, c in cells:
            out[r, c] = bg
    settled = set()
    while components:
        chosen = 0
        best = -h
        for i in range(len(components)):
            bottom = max(r for r, c in components[i])
            if bottom > best:
                best = bottom
                chosen = i
        cells = components.pop(chosen)
        limit = h
        for r, c in cells:
            limit = min(limit, h - 1 - r - gap)
            for y in range(r + 1, h):
                if grid[y, c] == terrain:
                    limit = min(limit, y - r - 1 - gap)
                if (y, c) in settled:
                    limit = min(limit, y - r - 1)
        shift = max(0, limit // step * step)
        for r, c in cells:
            out[r + shift, c] = grid[r, c]
            settled.add((r + shift, c))
    return out

def run(params, grid, demos):
    size = int(round(params['rule'][0]))
    density = float(params['rule'][1])
    kinds = int(round(params['rule'][2]))
    step = int(round(params['rule'][3]))
    height, width = grid.shape
    if size < 2 or step != 1 or kinds != 2:
        return grid.copy()
    best = None
    best_area = 0
    best_color = None
    for value in params['colors']:
        color = int(round(value))
        for top in range(height):
            for left in range(width):
                if grid[top, left] != color:
                    continue
                for bottom in range(top + size, height + step):
                    if not np.all(grid[top:bottom, left] == color):
                        break
                    for right in range(left + size, width + step):
                        area = (bottom - top) * (right - left)
                        if area <= best_area:
                            continue
                        block = grid[top:bottom, left:right]
                        if not np.all(block[0, :] == color):
                            continue
                        if not np.all(block[-step, :] == color):
                            continue
                        if not np.all(block[:, -step] == color):
                            continue
                        if np.count_nonzero(block == color) < density * area:
                            continue
                        if len(np.unique(block)) != kinds:
                            continue
                        best = block.copy()
                        best_area = area
                        best_color = color
    if best is None:
        return grid.copy()
    marker = None
    for value in params['colors']:
        color = int(round(value))
        if color != best_color and np.any(best == color):
            marker = color
            break
    if marker is None:
        return grid.copy()
    rows = np.any(best == marker, axis=1)
    cols = np.any(best == marker, axis=0)
    out = best.copy()
    out[rows, :] = marker
    out[:, cols] = marker
    return out

