        return out
    height, width = grid.shape
    occupied = np.any(grid == ink, axis=1)
    groups = []
    rows = []
    for r in range(height):
        if occupied[r]:
            if rows and r != rows[-1] + step:
                groups.append(rows)
                rows = []
            rows.append(r)
        elif rows:
            groups.append(rows)
            rows = []
    if rows:
        groups.append(rows)
    records = []
    template = None
    best = -step
    for group in groups:
        origin = group[0]
        columns = {}
        for c in range(width):
            state = tuple(r - origin for r in group if grid[r, c] == ink)
            if state:
                columns[c] = state
        if columns:
            end = max(columns)
            records.append((origin, columns, end))
            if end > best:
                best = end
                template = columns
    if template is None:
        return out
    transitions = {}
    for c in range(width - step):
        if c in template and c + step in template:
            transitions[template[c]] = template[c + step]
    for origin, columns, end in records:
        state = columns[end]
        for c in range(end + step, width, step):
            state = transitions.get(state, state)
            for offset in state:
                r = origin + offset
                if r >= 0 and r < height and out[r, c] == background:
                    out[r, c] = fill
    return out

