        pending = [seed]
        while pending:
            current = pending.pop()
            neighbors = []
            for point in remaining:
                dr = abs(point[0] - current[0])
                dc = abs(point[1] - current[1])
                if dr == dc and zero < dr <= gap:
                    neighbors.append(point)
            for point in neighbors:
                remaining.remove(point)
                group.append(point)
                pending.append(point)
        groups.append(group)
    for group in groups:
        solution = None
        for apex in group:
            for direction in directions:
                ar, ac = apex
                dr1, dc1, dr2, dc2 = direction
                count1 = zero
                count2 = zero
                extent = zero
                valid = True
                for rr, cc in group:
                    if rr == ar and cc == ac:
                        continue
                    t1 = (rr - ar) * dr1
                    t2 = (rr - ar) * dr2
                    if t1 > zero and rr == ar + t1 * dr1 and cc == ac + t1 * dc1:
                        count1 += step
                        extent = max(extent, t1)
                    elif t2 > zero and rr == ar + t2 * dr2 and cc == ac + t2 * dc2:
                        count2 += step
                        extent = max(extent, t2)
                    else:
                        valid = False
                        break
                if valid and count1 >= minimum and count2 >= minimum:
                    solution = (ar, ac, direction, extent)
                    break
            if solution is not None:
                break
        if solution is None:
            continue
        ar, ac, direction, extent = solution
        dr1, dc1, dr2, dc2 = direction
        for depth in range(zero, extent + step):
            r1 = ar + depth * dr1
            c1 = ac + depth * dc1
            r2 = ar + depth * dr2
            c2 = ac + depth * dc2
            if r1 == r2:
