                    if zero <= r1 < height and grid[r1, cc] != marker:
                        out[r1, cc] = paint
            else:
                for rr in range(max(zero, min(r1, r2)), min(height, max(r1, r2) + step)):
                    if zero <= c1 < width and grid[rr, c1] != marker:
                        out[rr, c1] = paint
    return out

