                    ta = target_left
                    tb = target_right
                elif a - left <= right - b:
                    ta = target_left + a - left
                    tb = ta + b - a
                else:
                    tb = target_right - (right - b)
                    ta = tb - (b - a)
                if ta >= sep + step and tb < w - step:
                    out[r, ta:tb + step] = color
    return np.rot90(out, -turns)

