            if index >= 0 and index < len(palette):
                out[mask, c] = palette[index]
        previous = mask.copy()
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    marker = int(round(params['rule'][1]))
    step = int(round(params['rule'][2]))
    minimum_length = int(round(params['rule'][3]))
    if step <= 0 or minimum_length <= step:
        return grid.copy()
    result = grid.copy()
    for axis_value in params['axes']:
        axis = int(round(axis_value))
        if axis == 0:
            source = grid
            target = result
        else:
            source = grid.T
            target = result.T
        height, width = source.shape
        for row in range(height):
            for start in range(width):
                if source[row, start] != marker:
                    continue
                if start >= step and source[row, start - step] == marker:
                    continue
                end = start
                while end < width and source[row, end] == marker:
                    end += step
                if end - start < minimum_length:
                    continue
                depth = row + step
                while depth < height:
                    seeds = []
                    for column in range(start, end, step):
                        value = source[depth, column]
                        if value != background and value != marker:
                            seeds.append(column)
                    if not seeds:
                        break
                    first = min(seeds)
                    last = max(seeds)
                    period = last - first + step
                    for column in range(start, end, step):
                        template_column = first + (column - first) % period
                        target[depth, column] = source[depth, template_column]
                    depth += step
    return result

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    ink = int(round(params['colors'][1]))
    unit = int(round(params['step'][0]))
    out = grid.copy()
    if bg == ink or unit != 1:
        return out
    points = np.argwhere(grid == ink)
    if len(points) == 0:
        return out
    low = np.min(points, axis=0)
    high = np.max(points, axis=0)
    for av in params['axes']:
        axis = int(round(av))
        if axis < 0 or axis > unit:
            return grid.copy()
        other = unit - axis
        for dv in params['directions']:
            direction = int(round(dv))
            if abs(direction) != unit:
                return grid.copy()
            if direction < 0:
                start = int(low[axis]) - unit
                stop = -unit
            else:
                start = int(high[axis]) + unit
                stop = grid.shape[axis]
            for lane in range(int(low[other]), int(high[other]) + unit):
                ray = []
                clear = True
                for position in range(start, stop, direction):
                    coord = [lane, lane]
                    coord[axis] = position
                    row, col = coord
                    ray.append((row, col))
                    if grid[row, col] != bg:
                        clear = False
                if clear:
                    for row, col in ray:
                        out[row, col] = ink
    return out

def run(params, grid, demos):
    colors = [int(round(v)) for v in params['palette']]
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['directions']]
    fraction = float(params['rule'][0])
    minimum = int(round(params['rule'][1]))
    length = int(round(params['rule'][2]))
    out = grid.copy()
    if length <= 0 or not any(dr != 0 or dc != 0 for dr, dc in directions):
        return out
    height, width = grid.shape
    best = []
    foreground = colors[0]
    for color in colors:
        seen = set()
        components = []
        for point in np.argwhere(grid == color):
            start = (int(point[0]), int(point[1]))
            if start in seen:
                continue
            seen.add(start)
            pending = [start]
            component = []
            while pending:
                r, c = pending.pop()
                component.append((r, c))
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < height and 0 <= nc < width and (nr, nc) not in seen and grid[nr, nc] == color:
                        seen.add((nr, nc))
                        pending.append((nr, nc))
            components.append(component)
        if len(components) > len(best):
            best = components
            foreground = color
    if len(best) < minimum:
        return out
    objects = []
    hosts = []
    for component in best:
        rows = {}
        columns = {}
        border = {}
        for r, c in component:
            rows[r] = rows.get(r, 0) + 1
            columns[c] = columns.get(c, 0) + 1
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width and grid[nr, nc] != foreground:
                    color = colors[int(grid[nr, nc])]
                    border[color] = border.get(color, 0) + 1
        if not border:
            continue
        host = max(border, key=border.get)
        if host not in hosts:
            hosts.append(host)
        row_limit = max(rows.values()) * fraction
        column_limit = max(columns.values()) * fraction
        core_rows = [r for r in rows if rows[r] >= row_limit]
        core_columns = [c for c in columns if columns[c] >= column_limit]
        if not core_rows or not core_columns:
            continue
        objects.append((component, host, min(core_rows), max(core_rows), min(core_columns), max(core_columns)))
    for component, host, top, bottom, left, right in objects:
        alternatives = [color for color in hosts if color != host]
        if not alternatives:
            continue
        paint = alternatives[0]
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if grid[r, c] != foreground:
                    for dr, dc in directions:
                        if not (top <= r + dr <= bottom and left <= c + dc <= right):
                            for distance in range(length):
                                nr, nc = r + distance * dr, c + distance * dc
                                if 0 <= nr < height and 0 <= nc < width:
                                    out[nr, nc] = paint
        for r, c in component:
            if top <= r <= bottom and left <= c <= right:
                continue
            for dr, dc in directions:
                if top <= r + dr <= bottom and left <= c + dc <= right:
                    for distance in range(length):
                        nr, nc = r + distance * dr, c + distance * dc
                        if 0 <= nr < height and 0 <= nc < width:
                            out[nr, nc] = paint
    return out

