                nr, nc = row + dr, col + dc
                if 0 <= nr < height and 0 <= nc < width:
                    point = (nr, nc)
                    if point not in seen and grid[nr, nc] == foreground:
                        seen.add(point)
                        pending.append(point)
        if len(component) <= noise_limit:
            continue
        top = min(row for row, col in component)
        bottom = max(row for row, col in component)
        left = min(col for row, col in component)
        right = max(col for row, col in component)
        horizontal = {(top + bottom - row, col) for row, col in component}
        vertical = {(row, left + right - col) for row, col in component}
        if horizontal == component:
            color = horizontal_color
        elif vertical == component:
            color = vertical_color
