    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    out = grid.copy()
    stones = np.argwhere(grid == obstacle)
    balls = np.argwhere(grid == ball)
    if len(stones) == 0 or len(balls) == 0:
        return out
    h, w = grid.shape
    r, c = int(balls[0][0]), int(balls[0][1])
    gaps = [int(np.min(stones[:, 0])) - r, r - int(np.max(stones[:, 0])), int(np.min(stones[:, 1])) - c, c - int(np.max(stones[:, 1]))]
    axis = int(np.argmax(np.array(gaps)))
    dr, dc = directions[axis]
    out[r, c] = bg
    for step in range(h * w):
        nr, nc = r + dr, c + dc
        if nr < 0 or nr >= h or nc < 0 or nc >= w:
            break
        if out[nr, nc] != bg:
            break
        r, c = nr, nc
    lateral = None
    for step in range(h * w):
        moved = False
        for lr, lc in directions:
            if dr * lr + dc * lc != 0:
                continue
            if lateral is not None and (lr, lc) != lateral:
                continue
            nr, nc = r + dr + lr, c + dc + lc
            if nr < 0 or nr >= h or nc < 0 or nc >= w:
                continue
            if out[nr, nc] != bg:
                continue
            touching = False
            for ar, ac in directions:
                rr, cc = nr + ar, nc + ac
                if 0 <= rr < h and 0 <= cc < w:
                    if out[rr, cc] == obstacle:
                        touching = True
            if touching:
                r, c = nr, nc
                lateral = (lr, lc)
                moved = True
                break
        if not moved:
            break
    out[r, c] = ball
    return out

