    for color in np.unique(grid):
        candidate_rows = [i for i, row in enumerate(grid) if np.mean(row == color) >= threshold]
        candidate_cols = [i for i, col in enumerate(grid.T) if np.mean(col == color) >= threshold]
        score = len(candidate_rows) + len(candidate_cols)
        if score > best:
            best = score
            rows = candidate_rows
            cols = candidate_cols
            divider = color
    holes = []
    for r in rows:
        for c in cols:
            if grid[r, c] != divider:
                holes.append((r, c))
    if not holes:
        return grid.copy()
    top = min(r for r, c in holes)
    bottom = max(r for r, c in holes)
    left = min(c for r, c in holes)
    right = max(c for r, c in holes)
    return grid[top:bottom + inclusive, left:right + inclusive].copy()

