    for r, c in points:
        for bottom, right in points:
            if bottom > r and right > c:
                if grid[r, right] == marker and grid[bottom, c] == marker:
                    out[r + inset:bottom, c + inset:right] = fill
    return out

def spans(active):
    result = []
    current = []
    for i in range(len(active)):
        if active[i]:
            current.append(i)
        elif current:
            result.append(current)
            current = []
    if current:
        result.append(current)
    return result

def run(params, grid, demos):
    corner_row = int(round(params['geometry'][0]))
    corner_col = int(round(params['geometry'][1]))
    minimum_count = int(round(params['geometry'][2]))
    background = int(grid[corner_row, corner_col])
    points = np.argwhere(grid != background)
    if len(points) == 0:
        return grid.copy()
    top = int(np.min(points[:, 0]))
    bottom = int(np.max(points[:, 0]))
    left = int(np.min(points[:, 1]))
    right = int(np.max(points[:, 1]))
    separator = int(grid[top, left])
    region = grid[top:bottom + 1, left:right + 1]
    occupied = region != separator
    rows = spans(np.sum(occupied, axis=1) >= minimum_count)
    columns = spans(np.sum(occupied, axis=0) >= minimum_count)
    if len(rows) == 0 or len(columns) == 0:
        return grid.copy()
    output_background = int(round(params['palette'][background]))
    output = np.full((len(rows), len(columns)), output_background, dtype=int)
    for r in range(len(rows)):
        for c in range(len(columns)):
            block = region[rows[r][0]:rows[r][-1] + 1, columns[c][0]:columns[c][-1] + 1]
            colors = block[(block != background) & (block != separator)]
            if len(colors) > 0:
                output[r, c] = int(round(params['palette'][int(colors[0])]))
    return output

def run(params, grid, demos):
