    repeats = int(round(params['config'][4]))
    if size <= 0 or gap < 0 or repeats <= 0 or fg < 0 or fg > 9 or bg < 0 or bg > 9:
        return np.zeros((1, 1), dtype=int)
    width = repeats * size + (repeats - 1) * gap
    if width <= 0 or width > 30:
        return np.zeros((1, 1), dtype=int)
    area = int(np.count_nonzero(grid == fg)) // (repeats * repeats)
    result = np.full((width, width), bg, dtype=int)
    for i in range(min(area, len(params['cells']))):
        row = int(round(params['cells'][i][0]))
        col = int(round(params['cells'][i][1]))
        if row < 0 or row >= size or col < 0 or col >= size:
            continue
        for r in range(repeats):
            for c in range(repeats):
                result[r * (size + gap) + row, c * (size + gap) + col] = fg
    return result

def run(params, grid, demos):
    bg = int(round(params['motion'][0]))
    step = int(round(params['motion'][1]))
    up = int(round(params['motion'][2]))
    down = int(round(params['motion'][3]))
    required = int(round(params['motion'][4]))
    if step <= 0 or up >= 0 or down <= 0:
        return grid.copy()
    h, w = grid.shape
    neighbors = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    seen = set()
    upper = []
    lower = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            color = int(grid[r, c])
            cells = [(r, c)]
            seen.add((r, c))
            pos = 0
            while pos < len(cells):
                y, x = cells[pos]
                pos += 1
                for dy, dx in neighbors:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny, nx] == color:
                        seen.add((ny, nx))
                        cells.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            corners = [(top, left), (top, right), (bottom, left), (bottom, right)]
            item = (top, bottom, left, right, cells, color)
            if sum(p in cells for p in corners) == required:
                upper.append(item)
            else:
                lower.append(item)
    upper.sort(key=lambda item: item[0])
    lower.sort(key=lambda item: item[1], reverse=True)
    out = np.full(grid.shape, bg, dtype=int)
    occupied = set()
    for objects, direction in [(upper, up), (lower, down)]:
        for top, bottom, left, right, cells, color in objects:
            if direction < 0:
                shift = -top
            else:
                shift = h - step - bottom
            while True:
                blocked = False
                for y in range(top + shift, bottom + shift + step):
                    for x in range(left, right + step):
                        if (y, x) in occupied:
                            blocked = True
                if not blocked:
                    break
                shift -= direction * step
                if top + shift < 0 or bottom + shift >= h:
                    return grid.copy()
            for y, x in cells:
                out[y + shift, x] = color
            for y in range(top + shift, bottom + shift + step):
                for x in range(left, right + step):
                    occupied.add((y, x))
    return out

def run(params, grid, demos):
    bg = int(round(params['config'][0]))
    panel = int(round(params['config'][1]))
    base = int(round(params['config'][2]))
    ink = int(round(params['config'][3]))
    size = int(round(params['config'][4]))
    inset = int(round(params['config'][5]))
    turns = int(round(params['config'][6]))
    out = grid.copy()
    if size <= 0 or inset <= 0 or turns <= 0 or bg == panel or base == ink:
        return grid * 0
    h, w = grid.shape
    panel_cols = np.any(grid == panel, axis=0)
    refs = {}
    for color in np.unique(grid[:, panel_cols]):
        color = int(color)
        if color == panel or color == bg:
            continue
        mask = (grid == color) & panel_cols
        pts = np.argwhere(mask)
        if len(pts) == 0:
            continue
        lo = np.min(pts, axis=0)
        hi = np.max(pts, axis=0)
        refs[color] = mask[lo[0]:hi[0]+1, lo[1]:hi[1]+1].copy()
    seen = set()
    for r in range(h):
        for c in range(w):
            if panel_cols[c] or grid[r,c] == bg or (r,c) in seen:
                continue
            cells = [(r,c)]
            seen.add((r,c))
            pos = 0
            while pos < len(cells):
                y, x = cells[pos]
                pos += 1
                for delta in params['neighbors']:
                    dy = int(round(delta[0]))
                    dx = int(round(delta[1]))
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if not panel_cols[xx] and grid[yy,xx] != bg and (yy,xx) not in seen:
                            seen.add((yy,xx))
                            cells.append((yy,xx))
            coords = np.array(cells)
            lo = np.min(coords, axis=0)
            hi = np.max(coords, axis=0)
            if hi[0]-lo[0]+1 != size or hi[1]-lo[1]+1 != size:
                continue
            y, x = int(lo[0]), int(lo[1])
            block = grid[y:y+size, x:x+size]
            colors = np.unique(block)
            if len(colors) == 1:
                color = int(colors[0])
                if color in refs:
                    pattern = refs[color]
                    ph, pw = pattern.shape
                    if ph + inset <= size and pw + inset <= size:
                        out[y:y+size,x:x+size] = base
                        region = out[y+inset:y+inset+ph,x+inset:x+inset+pw]
                        region[pattern] = ink
            else:
                mask = block == ink
                pts = np.argwhere(mask)
                if len(pts) == 0:
                    continue
                ml = np.min(pts, axis=0)
                mh = np.max(pts, axis=0)
                pattern = mask[ml[0]:mh[0]+1,ml[1]:mh[1]+1]
                found = None
                for color in refs:
                    reference = refs[color]
                    for k in range(turns):
                        rotated = np.rot90(pattern,k)
                        if rotated.shape == reference.shape:
                            if np.all(rotated == reference) or np.all(np.fliplr(rotated) == reference):
                                found = color
                    if found is not None:
                        break
                if found is not None:
                    out[y:y+size,x:x+size] = found
    return out

def run(params, grid, demos):
