def run(params, grid, demos):
    unit = int(round(params['layout'][0]))
    gap = int(round(params['layout'][1]))
    limit = int(round(params['layout'][2]))
    sizes = [int(round(v)) for v in params['sizes']]
    caps = [int(round(v)) for v in params['caps']]
    if unit <= 0 or gap < 0 or limit <= 0 or min(sizes) <= 0:
        return grid.copy()
    bg = int(np.argmax(np.bincount(grid.flatten())))
    height, width = grid.shape
    colors = []
    counts = []
    for side, cap in zip(sizes, caps):
        found = {}
        for r in range(height - side + unit):
            for c in range(width - side + unit):
                color = int(grid[r, c])
                if color == bg:
                    continue
                if r >= unit and grid[r - unit, c] == color:
                    continue
                if c >= unit and grid[r, c - unit] == color:
                    continue
                if r + side < height and grid[r + side, c] == color:
                    continue
                if c + side < width and grid[r, c + side] == color:
                    continue
                if np.all(grid[r:r + side, c:c + side] == color):
                    found[color] = found.get(color, 0) + unit
        if found:
            color = max(found, key=found.get)
            colors.append(color)
            counts.append(min(found[color], max(0, cap)))
        else:
            colors.append(bg)
            counts.append(0)
    slots = max(counts)
    if slots <= 0:
        return grid.copy()
    widths = []
    for j in range(slots):
        widths.append(max([side for side, count in zip(sizes, counts) if count > j]) + gap)
    out = np.full((max(sizes) + gap, sum(widths)), bg, dtype=int)
    left = 0
    for j in range(slots):
        for k in range(len(sizes) - unit, -unit, -unit):
            if counts[k] > j:
                side = sizes[k]
                out[0:side, left:left + side] = colors[k]
        left += widths[j]
    return out[:limit, :limit]

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    unit = int(round(params['rule'][1]))
    double = int(round(params['rule'][2]))
    threshold = int(round(params['rule'][3]))
    out = grid.copy()
    h, w = grid.shape
    if unit <= 0 or threshold <= 0:
        return out
    quadrants = [(int(round(v[0])), int(round(v[1]))) for v in params['quadrants']]
    neighbors = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    centers = []
    for r in range(h - unit):
        for c in range(w - unit):
            markers = []
            valid = True
            for dr, dc in quadrants:
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w):
                    valid = False
                    break
                markers.append(int(grid[rr, cc]))
            if valid:
                colors = [v for v in markers if v != bg]
                if len(set(colors)) >= threshold and len(colors) == len(set(colors)):
                    centers.append((r, c, markers))
    for r, c, markers in centers:
        shapes = []
        for k in range(len(quadrants)):
            color = markers[k]
            if color == bg:
                shapes.append([])
                continue
            dr, dc = quadrants[k]
            start = (r + dr, c + dc)
            seen = {start}
            pending = [start]
            points = []
            while pending:
                rr, cc = pending.pop()
                points.append((rr, cc))
                for vr, vc in neighbors:
                    nr, nc = rr + vr, cc + vc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                        if grid[nr, nc] == color:
                            seen.add((nr, nc))
                            pending.append((nr, nc))
            shapes.append(points)
        source = max(range(len(shapes)), key=lambda k: len(shapes[k]))
        sr, sc = quadrants[source]
        for k in range(len(quadrants)):
            color = markers[k]
            if color == bg:
                continue
            tr, tc = quadrants[k]
            for rr, cc in shapes[source]:
                nr = rr if sr == tr else double * r + unit - rr
                nc = cc if sc == tc else double * c + unit - cc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr, nc] = color
    return out

def place(board, pieces, index, turns, background):
    if index == len(pieces):
        return bool(np.all(board != background))
    color, mask = pieces[index]
    for turn in range(turns):
        shape = np.rot90(mask, turn)
        cells = np.argwhere(shape)
        height, width = shape.shape
        for row in range(board.shape[0] - height + 1):
            for col in range(board.shape[1] - width + 1):
                valid = True
                for cell in cells:
                    if board[row + int(cell[0]), col + int(cell[1])] != background:
                        valid = False
                        break
                if valid:
                    for cell in cells:
                        board[row + int(cell[0]), col + int(cell[1])] = color
                    if place(board, pieces, index + 1, turns, background):
                        return True
                    for cell in cells:
                        board[row + int(cell[0]), col + int(cell[1])] = background
    return False
