                continue
            color = int(grid[row, col])
            cells = [(row, col)]
            seen.add((row, col))
            cursor = 0
            while cursor < len(cells):
                current = cells[cursor]
                cursor += 1
                for dr, dc in directions:
                    rr = current[0] + dr
                    cc = current[1] + dc
                    if 0 <= rr < grid.shape[0] and 0 <= cc < grid.shape[1]:
                        if (rr, cc) not in seen and grid[rr, cc] == color:
                            seen.add((rr, cc))
                            cells.append((rr, cc))
            lowrow = min(cell[0] for cell in cells)
            highrow = max(cell[0] for cell in cells)
            lowcol = min(cell[1] for cell in cells)
            highcol = max(cell[1] for cell in cells)
            mask = np.zeros((highrow - lowrow + 1, highcol - lowcol + 1), dtype=int)
            for rr, cc in cells:
                mask[rr - lowrow, cc - lowcol] = 1
            pieces.append((color, mask))
    pieces = sorted(pieces, key=lambda piece: -int(np.sum(piece[1])))
    if sum(int(np.sum(piece[1])) for piece in pieces) != height * width:
