    if len(rows) == divisor:
        center = (min(rows) + max(rows)) // divisor
        for c in cols:
            out[:, c] = black
        for r in [center - step, center + step]:
            if 0 <= r < h:
                out[r, :] = black
        start = (w - count) // divisor
        for c in range(max(0, start), min(w, start + count)):
            out[center, c] = gray
    elif len(cols) == divisor:
        center = (min(cols) + max(cols)) // divisor
        for r in rows:
            out[r, :] = black
        for c in [center - step, center + step]:
            if 0 <= c < w:
                out[:, c] = black
