    inner = grid[inner_low[0]:inner_high[0]+1, inner_low[1]:inner_high[1]+1] == inner_color
    outer = grid[outer_low[0]:outer_high[0]+1, outer_low[1]:outer_high[1]+1] == outer_color
    palette = []
    for row in grid:
        for value in row:
            color = int(value)
            if color != bg and color != separator and color != inner_color and color != outer_color and color not in palette:
                palette.append(color)
    if foreground_index < 0 or background_index < 0 or foreground_index >= len(palette) or background_index >= len(palette):
        return grid.copy()
    mask = np.kron(outer, inner)
    return np.where(mask, palette[foreground_index], palette[background_index]).astype(int)

