def run(params, grid, demos):
    background = int(round(params['geometry'][0]))
    thickness = int(round(params['geometry'][1]))
    scale = int(round(params['geometry'][2]))
    limit = int(round(params['geometry'][3]))
    if thickness <= 0 or scale <= thickness or limit <= 0:
        return grid.copy()
    colors = [int(c) for c in np.unique(grid) if int(c) != background]
    rows = np.arange(grid.shape[0])[:, None]
    cols = np.arange(grid.shape[1])[None, :]
    evidence = {}
    for c in colors:
        points = np.argwhere(grid == c)
        top = int(np.min(points[:, 0]))
        bottom = int(np.max(points[:, 0]))
        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1]))
        inside = (rows >= top) & (rows <= bottom) & (cols >= left) & (cols <= right)
        border = inside & ((rows < top + thickness) | (rows > bottom - thickness) | (cols < left + thickness) | (cols > right - thickness))
        for other in colors:
            evidence[(c, other)] = int(np.count_nonzero(border & (grid == other))) if other != c else 0
    memo = {}
    score, order = arrange(tuple(colors), evidence, memo)
    size = scale * len(order) - thickness
    if size <= 0 or size > limit:
        return grid.copy()
    output = np.full((size, size), background, dtype=int)
    for index, c in enumerate(order):
        margin = index * thickness
        if margin < size - margin:
            output[margin:size - margin, margin:size - margin] = c
    return output
def arrange(colors, evidence, memo):
    if not colors:
        return 0, []
    if colors in memo:
        return memo[colors]
    best_score = None
    best_order = []
    for c in colors:
        rest = tuple(d for d in colors if d != c)
        score, order = arrange(rest, evidence, memo)
        score += sum(evidence[(d, c)] for d in rest)
        if best_score is None or score > best_score:
            best_score = score
            best_order = order + [c]
    memo[colors] = (best_score, best_order)
    return memo[colors]

