    out = np.full((h, w), bg, dtype=int)
    seen = set()
    for row in range(h):
        for col in range(w):
            if (row, col) in seen or int(grid[row, col]) == bg:
                continue
            color = int(grid[row, col])
            change = 0
            for rule in params['rules']:
                if color == int(round(rule[0])):
                    change = int(round(rule[1]))
            points = [(row, col)]
            seen.add((row, col))
            index = 0
            while index < len(points):
                y, x = points[index]
                index += 1
                for offset in params['neighbors']:
                    dy = int(round(offset[0]))
                    dx = int(round(offset[1]))
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and int(grid[yy, xx]) == color:
                        seen.add((yy, xx))
                        points.append((yy, xx))
            best = None
            for cy in range(h):
                for cx in range(w):
                    radius = abs(points[0][0] - cy) + abs(points[0][1] - cx)
                    valid = True
                    for y, x in points:
                        if abs(y - cy) + abs(x - cx) != radius:
                            valid = False
                            break
                    if valid and (best is None or radius < best[0]):
                        best = (radius, cy, cx)
            if best is None:
                for y, x in points:
                    out[y, x] = color
                continue
            radius, cy, cx = best
            if change > 0 and radius == edge_radius and len(points) == edge_count and cy == h - unit:
                cx += edge_shift
            radius += change
            for y in range(h):
                for x in range(w):
                    if abs(y - cy) + abs(x - cx) == radius:
                        out[y, x] = color
    return out

def run(params, grid, demos):
