    for position in np.argwhere(np.logical_or(grid == paint, grid == block)):
        start = (int(position[0]), int(position[1]))
        if start in seen:
            continue
        seen.add(start)
        pending = [start]
        orange = []
        gray = []
        while pending:
            r, c = pending.pop()
            if grid[r, c] == paint:
                gray.append((r, c))
            else:
                orange.append((r, c))
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= height or nc < 0 or nc >= width:
                    continue
                point = (nr, nc)
                if point in seen:
