                    pending.append(point)
        if not orange or not gray:
            continue
        rows = [point[0] for point in orange]
        cols = [point[1] for point in orange]
        if min(rows) == top:
            span = len(set(cols))
            depth = len(gray) // span
            for r, c in orange:
                if r - top < depth:
                    out[r, c] = paint
        elif max(rows) == bottom:
            span = len(set(cols))
            depth = len(gray) // span
            for r, c in orange:
                if bottom - r < depth:
                    out[r, c] = paint
        elif min(cols) == left:
            span = len(set(rows))
            depth = len(gray) // span
            for r, c in orange:
                if c - left < depth:
                    out[r, c] = paint
        elif max(cols) == right:
            span = len(set(rows))
            depth = len(gray) // span
            for r, c in orange:
                if right - c < depth:
                    out[r, c] = paint
    return out

def run(params, grid, demos):
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    cutoff = int(round(params['rules'][0]))
    singleton = int(round(params['rules'][1]))
    minimum = int(round(params['rules'][2]))
    h, w = grid.shape
    colors, counts = np.unique(grid, return_counts=True)
    bg = int(colors[np.argmax(counts)])
    points = set((int(p[0]), int(p[1])) for p in np.argwhere(grid != bg))
    remaining = points.copy()
    components = []
    while remaining:
        seed = remaining.pop()
        component = [seed]
        queue = [seed]
        while queue:
            r, c = queue.pop()
            for dr, dc in directions:
                neighbor = (r + dr, c + dc)
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    component.append(neighbor)
                    queue.append(neighbor)
        components.append(component)
    templates = [component for component in components if len(component) > cutoff]
    source = set()
    for component in templates:
        source.update(component)
    targets = points - source
    out = grid.copy()
    for color, count in zip(colors, counts):
        if int(color) != bg and int(count) <= singleton:
            for r, c in source:
                if int(grid[r, c]) == int(color):
                    out[r, c] = bg
    candidates = []
    for component in templates:
        shifts = set()
        for r, c in targets:
            for sr, sc in component:
                if int(grid[r, c]) == int(grid[sr, sc]):
                    shifts.add((r - sr, c - sc))
        for dr, dc in sorted(shifts):
            cells = []
            matched = set()
            valid = True
            for sr, sc in component:
                r, c = sr + dr, sc + dc
                if r < 0 or r >= h or c < 0 or c >= w or (r, c) in source:
                    valid = False
                    break
                color = int(grid[sr, sc])
                existing = int(grid[r, c])
                if existing != bg and existing != color:
                    valid = False
                    break
                if (r, c) in targets and existing == color:
                    matched.add((r, c))
                cells.append((r, c, color))
            if valid and len(matched) >= minimum:
                candidates.append((cells, matched))
    uncovered = targets.copy()
    while uncovered:
        best = None
        best_score = minimum - 1
        for cells, matched in candidates:
            score = len(matched & uncovered)
            if score <= best_score:
                continue
            valid = True
            for r, c, color in cells:
                if int(out[r, c]) != bg and int(out[r, c]) != color:
                    valid = False
                    break
            if valid:
                best = (cells, matched)
                best_score = score
        if best is None:
            break
        cells, matched = best
        for r, c, color in cells:
            out[r, c] = color
        uncovered = uncovered - matched
    return out

def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    trail = int(round(params['colors'][1]))
    obstacle = int(round(params['colors'][2]))
    up = int(round(params['motion'][0]))
    right = int(round(params['motion'][1]))
    lower = int(round(params['motion'][2]))
    out = grid.copy()
    height, width = grid.shape
    start = height + up
    if start < lower or start >= height or up >= lower or right <= lower:
        return out
    seeds = np.argwhere(grid[start] == trail)
    for seed in seeds:
        col = int(seed[0])
        row = start
        while lower <= row < height and lower <= col < width:
            if grid[row, col] == background or grid[row, col] == trail:
                out[row, col] = trail
            ahead = row + up
            if ahead < lower or ahead >= height:
                break
            while lower <= col < width and grid[ahead, col] == obstacle:
                col = col + right
                if lower <= col < width:
                    if grid[row, col] == background or grid[row, col] == trail:
                        out[row, col] = trail
            row = ahead
    return out

def run(params, grid, demos):
    step = int(round(params['geometry'][0]))
    divisor = int(round(params['geometry'][1]))
    if step <= 0 or divisor <= step:
        return grid.copy()
    zero = step - step
    work = grid.copy()
    transposed = work.shape[0] < work.shape[1]
    if transposed:
        work = work.T.copy()
    background = work[zero, zero]
    occupied = np.any(work != background, axis=1)
    positions = np.where(occupied)[0]
    if len(positions) < divisor:
        return grid.copy()
    first = int(positions[zero])
    last = int(positions[len(positions) - step])
    gaps = []
    for row in range(first, last + step):
        if not occupied[row]:
            gaps.append(row)
    if len(gaps) == zero:
        return grid.copy()
    start = gaps[zero]
    end = gaps[len(gaps) - step] + step
    extent = (end - start) // divisor
    first_colors = work[first][work[first] != background]
    last_colors = work[last][work[last] != background]
    upper_color = int(first_colors[zero])
    lower_color = int(last_colors[zero])
    work[start:start + extent, :] = upper_color
    work[end - extent:end, :] = lower_color
    if transposed:
        work = work.T.copy()
    return work

def run(params, grid, demos):
    seed = int(round(params['rule'][0]))
    alternate = int(round(params['rule'][1]))
    spread = int(round(params['rule'][2]))
    period = int(round(params['rule'][3]))
    direction = int(round(params['rule'][4]))
    out = grid.copy()
    points = np.argwhere(grid == seed)
    if len(points) == 0 or period <= 0 or spread <= 0:
        return out
    top = int(np.min(points[:, 0]))
    bottom = int(np.max(points[:, 0]))
    center = int(points[0, 1])
    for r in range(grid.shape[0]):
        distance = direction * (r - bottom)
        if r >= top and distance >= 0:
            for c in range(grid.shape[1]):
                offset = abs(c - center)
                if offset <= distance * spread:
                    if offset % period == 0:
                        out[r, c] = seed
                    else:
                        out[r, c] = alternate
    return out

def run(params, grid, demos):
    arms = [int(round(v)) for v in params['arms']]
    inset = int(round(params['geometry'][0]))
    gap = int(round(params['geometry'][1]))
    if inset <= 0 or gap <= 0:
        return grid.copy()
    colors, counts = np.unique(grid, return_counts=True)
    bg = int(colors[np.argmax(counts)])
    height, width = grid.shape
    for point in np.argwhere(grid != bg):
        r, c = int(point[0]), int(point[1])
        color = int(grid[r, c])
        for arm in arms:
            if arm <= 0:
                continue
            for h in range(arm + arm + gap, height - r + 1):
                if grid[r + h - inset, c] != color:
                    continue
                for w in range(arm + arm + gap, width - c + 1):
                    if grid[r, c + w - inset] != color or grid[r + h - inset, c + w - inset] != color:
                        continue
                    valid = True
                    for x in range(w):
                        expected = color if x < arm or x >= w - arm else bg
                        if grid[r, c + x] != expected or grid[r + h - inset, c + x] != expected:
                            valid = False
                            break
                    if not valid:
                        continue
                    for y in range(h):
                        expected = color if y < arm or y >= h - arm else bg
                        if grid[r + y, c] != expected or grid[r + y, c + w - inset] != expected:
                            valid = False
                            break
                    if not valid:
                        continue
                    interior = grid[r + inset:r + h - inset, c + inset:c + w - inset]
                    points = np.argwhere(interior != bg)
                    if len(points) == 0:
                        continue
                    if not np.all(interior[interior != bg] == color):
                        continue
                    lo = np.min(points, axis=0)
                    hi = np.max(points, axis=0)
                    return interior[int(lo[0]):int(hi[0]) + inset, int(lo[1]):int(hi[1]) + inset].copy()
    return grid.copy()

def run(params, grid, demos):
    colors, counts = np.unique(grid, return_counts=True)
    marker = colors[int(np.argmax(counts * params['selection'][0]))]
    votes = np.zeros(len(colors))
