        nearby = np.zeros(len(colors))
        for offset in params['offsets']:
            row = int(point[0]) + int(round(offset[0]))
            col = int(point[1]) + int(round(offset[1]))
            if 0 <= row < grid.shape[0] and 0 <= col < grid.shape[1]:
                nearby += (colors == grid[row, col])
        owner = int(np.argmax(nearby * params['selection'][1]))
        votes[owner] += params['selection'][2]
    winner = int(colors[int(np.argmax(votes))])
    size = int(round(params['size'][0]))
    if size <= 0 or size > grid.shape[0] or size > grid.shape[1]:
        return grid.copy()
    return np.full((size, size), winner, dtype=int)

def run(params, grid, demos):
