        return out
    extent = count * side + (count - 1) * gap
    if grid.shape[0] != extent or grid.shape[1] != extent:
        return out
    colors = [int(c) for c in np.unique(grid) if int(c) != bg]
    blocks = []
    target = {}
    for color in colors:
        target[color] = 0
    for br in range(count):
        for bc in range(count):
            r = br * (side + gap)
            c = bc * (side + gap)
            block = grid[r:r + side, c:c + side]
            blocks.append((r, c, block))
            for color in colors:
                amount = int(np.count_nonzero(block == color))
                target[color] = max(target[color], amount)
    for r, c, block in blocks:
        missing = []
        for color in colors:
            amount = target[color] - int(np.count_nonzero(block == color))
            for k in range(amount):
                missing.append(color)
        holes = np.argwhere(block == bg)
        if len(missing) == len(holes):
            for k in range(len(missing)):
                rr = int(holes[k][0])
                cc = int(holes[k][1])
                out[r + rr, c + cc] = missing[k]
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    anchor = int(round(params['rule'][1]))
    axis = int(round(params['rule'][2]))
    if axis < 0 or axis >= len(grid.shape) or anchor == background:
        return grid.copy()
    anchor_points = np.argwhere(grid == anchor)
    if len(anchor_points) == 0:
        return grid.copy()
    target = int(np.min(anchor_points[:, axis]))
    result = np.full(grid.shape, background, dtype=int)
    for color in np.unique(grid):
        if color == background:
            continue
        points = np.argwhere(grid == color)
        start = int(np.min(points[:, axis]))
        for point in points:
            destination = point.tolist()
            destination[axis] += target - start
            if all(value >= 0 and value < size for value, size in zip(destination, grid.shape)):
                result[tuple(destination)] = int(color)
    return result

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    marker = int(round(params['rule'][1]))
    origin = int(round(params['rule'][2]))
    shift = int(round(params['rule'][3]))
    step = int(round(params['rule'][4]))
    height, width = grid.shape
    if origin < 0 or origin >= width or origin >= height or step <= 0:
        return grid.copy()
    block = int(np.count_nonzero(grid[:, origin] == marker))
    columns = []
    for column in range(width):
        color = int(grid[origin, column])
        if color != background and color != marker:
            columns.append(column)
    if block <= 0 or len(columns) == 0:
        return grid.copy()
    destination = columns[origin] + shift
    if destination < 0 or destination >= width:
        return grid.copy()
    palette = [int(grid[origin, column]) for column in columns]
    output = grid.copy()
    for column in columns:
        output[:, column] = background
    for row in range(height):
        index = ((row // block) * step) % len(palette)
        output[row, destination] = palette[index]
    return output

def run(params, grid, demos):
    target = int(round(params['target'][0]))
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['directions']]
    bends = [(int(round(v[0])), int(round(v[1])), int(round(v[2])), int(round(v[3]))) for v in params['bends']]
    palette = {int(round(k)): int(round(v)) for k, v in zip(params['counts'], params['colors'])}
    result = grid.copy()
    seen = set()
    height, width = grid.shape
    for row in range(height):
        for col in range(width):
            if grid[row, col] != target or (row, col) in seen:
                continue
            component = set([(row, col)])
            seen.add((row, col))
            pending = [(row, col)]
            while pending:
                r, c = pending.pop()
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if grid[nr, nc] == target and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            component.add((nr, nc))
                            pending.append((nr, nc))
            count = 0
            for r, c in component:
                for ar, ac, br, bc in bends:
                    if (r + ar, c + ac) in component and (r + br, c + bc) in component:
                        count += 1
            color = palette.get(count, target)
            for r, c in component:
                result[r, c] = color
    return result

def run(params, grid, demos):
    target = int(round(params['colors'][0]))
    single = int(round(params['colors'][1]))
    pair = int(round(params['colors'][2]))
    larger = int(round(params['colors'][3]))
    single_size = int(round(params['sizes'][0]))
    pair_size = int(round(params['sizes'][1]))
    steps = []
    for row in params['steps']:
        steps.append((int(round(row[0])), int(round(row[1]))))
    out = grid.copy()
    seen = set()
    height, width = grid.shape
    for r in range(height):
        for c in range(width):
            if grid[r, c] != target or (r, c) in seen:
                continue
            component = [(r, c)]
            seen.add((r, c))
            pending = [(r, c)]
            while pending:
                y, x = pending.pop()
                for dy, dx in steps:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < height and 0 <= nx < width:
                        if grid[ny, nx] == target and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            component.append((ny, nx))
                            pending.append((ny, nx))
            color = larger
            if len(component) == single_size:
                color = single
            elif len(component) == pair_size:
                color = pair
            for y, x in component:
                out[y, x] = color
    return out

def run(params, grid, demos):
    period = int(round(params['pattern'][0]))
    row_step = int(round(params['pattern'][1]))
    out = grid.copy()
    if period <= 0:
        return out
    height, width = grid.shape
    for r in range(height):
        for c in range(width):
            source_row = (r + row_step * (c % period)) % height
            out[r, c] = grid[source_row, c]
    return out

def run(params, grid, demos):
    separator, background, step = [int(round(v)) for v in params['layout']]
    priorities = [int(round(v)) for v in params['priorities']]
    rows = [i for i, row in enumerate(grid) if np.all(row == separator)]
    cols = [i for i, col in enumerate(grid.T) if np.all(col == separator)]
    if not rows or not cols:
        return grid.copy()
    r = rows[0]
    c = cols[0]
    panels = [grid[:r, :c], grid[:r, c + step:], grid[r + step:, :c], grid[r + step:, c + step:]]
    out = np.full(panels[0].shape, background)
    for color in priorities:
        for panel in panels:
            if panel.shape != out.shape:
                return grid.copy()
            out = np.where(panel == color, color, out)
    return out.astype(int)

def run(params, grid, demos):
    palette = [int(round(v)) for v in params['palette']]
    divisor = int(round(params['split'][0]))
    if divisor <= 1:
        return grid.copy()
    best = None
    best_score = -1
    for axis in range(len(grid.shape)):
        cut = grid.shape[axis] // divisor
        if cut <= 0 or cut >= grid.shape[axis]:
            continue
        if axis == 0:
            a, b = grid[:cut, :], grid[cut:, :]
        else:
            a, b = grid[:, :cut], grid[:, cut:]
        ca = [int(np.count_nonzero(a == c)) for c in palette]
        cb = [int(np.count_nonzero(b == c)) for c in palette]
        ia = int(np.argmax(np.array(ca)))
        ib = int(np.argmax(np.array(cb)))
        if palette[ia] == palette[ib]:
            continue
        score = ca[ia] + cb[ib]
        if score > best_score:
            best_score = score
            best = (a, b, palette[ia], palette[ib])
    if best is None:
        return grid.copy()
    a, b, ba, bb = best
    if np.count_nonzero(a != ba) > np.count_nonzero(b != bb):
        source, target, source_bg, target_bg = a, b, ba, bb
    else:
        source, target, source_bg, target_bg = b, a, bb, ba
    candidates = [c for c in palette if c != source_bg]
    if len(candidates) == 0:
        return target.copy()
    counts = [int(np.count_nonzero(source == c)) for c in candidates]
    fill = candidates[int(np.argmax(np.array(counts)))]
    neighbours = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbours']]
    visited = np.zeros(source.shape, dtype=int)
    objects = []
    for r in range(source.shape[0]):
        for c in range(source.shape[1]):
            if visited[r, c] or source[r, c] == source_bg:
                continue
            pending = [(r, c)]
            visited[r, c] = 1
            cells = []
            while pending:
                y, x = pending.pop()
                cells.append((y, x))
                for dy, dx in neighbours:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < source.shape[0] and 0 <= nx < source.shape[1]:
                        if not visited[ny, nx] and source[ny, nx] != source_bg:
                            visited[ny, nx] = 1
                            pending.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells) + 1
            left = min(x for y, x in cells)
            right = max(x for y, x in cells) + 1
            objects.append(source[top:bottom, left:right].copy())
    result = target.copy()
    for obj in objects:
        markers = (obj != source_bg) & (obj != fill)
        if not np.any(markers):
            continue
        expected = np.where(markers, obj, target_bg)
        height, width = obj.shape
        for y in range(target.shape[0] - height + 1):
            for x in range(target.shape[1] - width + 1):
                region = target[y:y + height, x:x + width]
                if np.all(region == expected):
                    result[y:y + height, x:x + width] = np.where(obj != source_bg, obj, result[y:y + height, x:x + width])
    return result

def run(params, grid, demos):
    corner = int(round(params['geometry'][0]))
    thickness = int(round(params['geometry'][1]))
    growth = int(round(params['geometry'][2]))
    if thickness <= 0 or growth <= thickness:
        return grid.copy()
    current = grid.copy()
    colors = []
    while True:
        if corner < 0 or corner >= min(current.shape):
            return grid.copy()
        color = int(current[corner, corner])
        colors.append(color)
        points = np.argwhere(current != color)
        if len(points) == 0:
            break
        low = np.min(points, axis=0)
        high = np.max(points, axis=0)
        current = current[int(low[0]):int(high[0]) + thickness, int(low[1]):int(high[1]) + thickness]
    size = growth * len(colors) - thickness
    if size <= 0 or size > 30:
        return grid.copy()
    result = np.full((size, size), colors[0], dtype=int)
    for depth, color in enumerate(colors):
        margin = depth * thickness
        result[margin:size - margin, margin:size - margin] = color
    return result

def run(params, grid, demos):
    size = int(round(params['canvas'][0]))
    background = int(round(params['canvas'][1]))
    if size <= 0 or size > min(grid.shape) or not np.any(grid == background):
        return grid.copy()
    out = np.full((size, size), background)
    for layer in params['layers']:
        color = int(round(layer[0]))
        row = int(round(layer[1]))
        col = int(round(layer[2]))
        if row < 0 or col < 0 or row + size > grid.shape[0] or col + size > grid.shape[1]:
            return grid.copy()
        patch = grid[row:row + size, col:col + size]
        out = np.where(patch == color, patch, out)
    return out

def run(params, grid, demos):
    blank = int(round(params['layout'][0]))
    split = int(round(params['layout'][1]))
    col = int(round(params['layout'][2]))
    rows = [int(round(v)) for v in params['rows']]
    h = len(grid)
    w = len(grid[0])
    split = max(0, min(h - 1, split))
    col = max(0, min(w - 1, col))
    rows = [max(0, min(h - 1, r)) for r in rows]
    colors = [int(grid[r, col]) for r in rows]
    background = int(grid[split, col])
    out = grid.copy()
    for r in range(split, h):
        for c in range(w):
            if int(grid[r, c]) != background and int(grid[r, c]) not in colors:
                out[r, c] = background
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['neighbors']]
    for row, color in zip(rows, colors):
        seen = set()
        count = 0
        for r in range(split, h):
            for c in range(w):
                if int(grid[r, c]) == color and (r, c) not in seen:
                    count += 1
                    seen.add((r, c))
                    queue = [(r, c)]
                    while queue:
                        a, b = queue.pop()
                        for dr, dc in directions:
                            nr = a + dr
                            nc = b + dc
                            if split <= nr < h and 0 <= nc < w:
                                if (nr, nc) not in seen and int(grid[nr, nc]) == color:
                                    seen.add((nr, nc))
                                    queue.append((nr, nc))
        out[row, :] = blank
        for c in range(col, min(w, col + count)):
            out[row, c] = color
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    blue = int(round(params['rule'][1]))
    scale = int(round(params['rule'][2]))
    dr = int(round(params['rule'][3]))
    dc = int(round(params['rule'][4]))
    if scale <= 0:
        return grid.copy()
    h, w = grid.shape
    marked = np.zeros((h, w), dtype=int)
    seeds = np.argwhere(grid != bg)
    for seed in seeds:
        r, c = int(seed[0]), int(seed[1])
        for t in range(h * w):
            marked[(r + t * dr) % h, (c + t * dc) % w] = blue
    out = np.full((h * scale, w * scale), bg, dtype=int)
    for r in range(h):
        for c in range(w):
            if grid[r, c] != bg:
                out[r * scale:(r + 1) * scale, c * scale:(c + 1) * scale] = grid[r, c]
            elif marked[r, c] == blue:
                for k in range(scale):
                    out[r * scale + (k * dr) % scale, c * scale + (k * dc) % scale] = blue
    return out

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    divisor = max(1, int(round(params['center'][0])))
    directions = []
    for row in params['neighbors']:
        directions.append((int(round(row[0])), int(round(row[1]))))
    rotation = []
    for row in params['rotation']:
        rotation.append((int(round(row[0])), int(round(row[1]))))
    height, width = grid.shape
    result = np.full(grid.shape, bg)
    seen = set()
    for r in range(height):
        for c in range(width):
            if grid[r, c] == bg or (r, c) in seen:
                continue
            color = int(grid[r, c])
            pending = [(r, c)]
            seen.add((r, c))
            component = []
            while pending:
                a, b = pending.pop()
                component.append((a, b))
                for dr, dc in directions:
                    nr, nc = a + dr, b + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if (nr, nc) not in seen and grid[nr, nc] == color:
                            seen.add((nr, nc))
                            pending.append((nr, nc))
            rows = [point[0] for point in component]
            cols = [point[1] for point in component]
            cr = (min(rows) + max(rows)) // divisor
            cc = (min(cols) + max(cols)) // divisor
            for a, b in component:
                dr, dc = a - cr, b - cc
                nr = cr + rotation[0][0] * dr + rotation[0][1] * dc
                nc = cc + rotation[1][0] * dr + rotation[1][1] * dc
                if 0 <= nr < height and 0 <= nc < width:
                    result[nr, nc] = color
    return result

def run(params, grid, demos):
    background = int(round(params['values'][0]))
    ray = int(round(params['values'][1]))
    marker = int(round(params['values'][2]))
    step = int(round(params['values'][3]))
    origin = int(round(params['values'][4]))
    positive = int(round(params['shifts'][0]))
    negative = int(round(params['shifts'][1]))
    if step <= origin or background == ray or ray == marker:
        return grid.copy()
    chosen = None
    rotation = origin
    for value in params['rotations']:
        k = int(round(value))
        candidate = np.rot90(grid, k)
        points = np.argwhere(candidate == ray)
        if len(points) > origin and np.all(points[:, 0] == origin):
            chosen = candidate.copy()
            rotation = k
            break
    if chosen is None:
        return grid.copy()
    height, width = chosen.shape
    seeds = np.argwhere(chosen[origin] == ray).flatten().tolist()
    markers = np.argwhere(chosen == marker)
    if len(markers) == origin:
        return grid.copy()
    left = np.count_nonzero(markers[:, 1] == origin)
    right = np.count_nonzero(markers[:, 1] == width - step)
    direction = positive if left > right else negative
    shift = origin
    for row in range(origin, height, step):
        if np.any(markers[:, 0] == row):
            shift += direction
        for column in seeds:
            target = column + shift
            if origin <= target < width:
                if chosen[row, target] == background or chosen[row, target] == ray:
                    chosen[row, target] = ray
    return np.rot90(chosen, -rotation).copy()

def run(params, grid, demos):
    near = int(round(params['colours'][0]))
    far = int(round(params['colours'][1]))
    marker = int(round(params['colours'][2]))
    zero = int(round(params['zero'][0]))
    out = grid.copy()
    height, width = grid.shape
    markers = np.argwhere(grid == marker)
    for direction in params['directions']:
        dr = int(round(direction[0]))
        dc = int(round(direction[1]))
        if dr == zero and dc == zero:
            continue
        for r in range(height):
            for c in range(width):
                rr = r + dr
                cc = c + dc
                if rr < zero or rr >= height or cc < zero or cc >= width:
                    continue
                a = grid[r, c]
                b = grid[rr, cc]
                if not ((a == near and b == far) or (a == far and b == near)):
                    continue
                closest = None
                position = None
                for point in markers:
                    mr = int(point[0])
                    mc = int(point[1])
                    if (mr - r) * dc != (mc - c) * dr:
                        continue
                    distance = (mr - r) * dr + (mc - c) * dc
                    if closest is None or abs(distance) < closest:
                        closest = abs(distance)
                        position = distance
                if position is None:
                    continue
                if position < zero:
                    out[r, c] = near
                    out[rr, cc] = far
                elif position > zero:
                    out[r, c] = far
                    out[rr, cc] = near
    return out

def run(params, grid, demos):
    bg = int(round(params['base'][0]))
    unit = int(round(params['base'][1]))
    out = np.full(grid.shape, bg, dtype=int)
    for rule in params['motion']:
        color = int(round(rule[0]))
        dr = int(round(rule[1]))
        dc = int(round(rule[2]))
        points = np.argwhere(grid == color)
        if len(points) == 0:
            continue
        rows = points[:, 0]
        cols = points[:, 1]
        sr = 0
        sc = 0
        if dr < 0:
            sr = dr * int(np.min(rows))
        elif dr > 0:
            sr = dr * (grid.shape[0] - unit - int(np.max(rows)))
        if dc < 0:
            sc = dc * int(np.min(cols))
        elif dc > 0:
            sc = dc * (grid.shape[1] - unit - int(np.max(cols)))
        for point in points:
            r = int(point[0]) + sr
            c = int(point[1]) + sc
            if 0 <= r < grid.shape[0] and 0 <= c < grid.shape[1]:
                out[r, c] = color
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    barrier = int(round(params['rule'][1]))
    offset = int(round(params['rule'][2]))
    row_axis = int(round(params['axes'][0]))
    col_axis = int(round(params['axes'][1]))
    result = np.full(grid.shape, background)
    walls = np.argwhere(grid == barrier)
    if len(walls) == 0:
        return result
    for point in walls:
        result[point[row_axis], point[col_axis]] = barrier
    rows = np.unique(walls[:, row_axis])
    cols = np.unique(walls[:, col_axis])
    vertical = len(rows) > len(cols)
    points = np.argwhere(np.logical_and(grid != background, grid != barrier))
    if vertical:
        line = int(cols[0])
        for point in points:
            r = int(point[row_axis])
            c = int(point[col_axis])
            if grid[r, line] == barrier:
                destination = line - offset if c < line else line + offset
                if 0 <= destination < grid.shape[col_axis]:
                    result[r, destination] = grid[r, c]
    else:
        line = int(rows[0])
        for point in points:
            r = int(point[row_axis])
            c = int(point[col_axis])
            if grid[line, c] == barrier:
                destination = line - offset if r < line else line + offset
                if 0 <= destination < grid.shape[row_axis]:
                    result[destination, c] = grid[r, c]
    return result

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    order_weight = float(params['rule'][1])
    width = int(round(params['rule'][2]))
    ranked = []
    for value in np.unique(grid):
        colour = int(value)
        if colour != background:
            size = int(np.count_nonzero(grid == colour))
            ranked.append((order_weight * size, colour))
    ranked.sort()
    return np.array([[colour] * width for score, colour in ranked], dtype=int)

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    green = int(round(params['colors'][1]))
    arm = int(round(params['distances'][0]))
    start = int(round(params['distances'][1]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    h, w = grid.shape
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == green:
                continue
            valid = True
            for dr, dc in directions:
                rr = r + arm * dr
                cc = c + arm * dc
                if rr < 0 or rr >= h or cc < 0 or cc >= w:
                    valid = False
                    break
                if grid[rr, cc] != green:
                    valid = False
                    break
            if valid:
                centers.append((r, c, int(grid[r, c])))
    out = grid.copy()
    for dr, dc in directions:
        if dr == 0 and dc == 0:
            continue
        for r, c, color in centers:
            rr = r + start * dr
            cc = c + start * dc
            while rr >= 0 and rr < h and cc >= 0 and cc < w:
                if grid[rr, cc] == green:
                    break
                out[rr, cc] = bg if color == bg else color
                rr += dr
                cc += dc
    return out

def run(params, grid, demos):
    bg = int(round(params['geometry'][0]))
    ink = int(round(params['geometry'][1]))
    wall = int(round(params['geometry'][2]))
    step = int(round(params['geometry'][3]))
    out = grid.copy()
    if step <= 0 or step > min(grid.shape):
        return out
    seeds = np.argwhere(grid == ink)
    if len(seeds) != 1 or bg == ink or ink == wall or bg == wall:
        return out
    horizontal = np.max(np.sum(grid == wall, axis=1))
    vertical = np.max(np.sum(grid == wall, axis=0))
    transposed = vertical > horizontal
    work = grid.T.copy() if transposed else grid.copy()
    barriers = [r for r in range(work.shape[0]) if np.any(work[r] == wall)]
    if len(barriers) == 0:
        return out
    seed = np.argwhere(work == ink)[0]
    reversed = int(seed[0]) > barriers[0]
    if reversed:
        work = np.flipud(work).copy()
    result = work.copy()
    seed = np.argwhere(work == ink)[0]
    active = set([int(seed[1])])
    previous = int(seed[0]) - step
    barriers = [r for r in range(work.shape[0]) if np.any(work[r] == wall) and r > int(seed[0])]
    for row in barriers:
        following = set()
        for col in active:
            for r in range(previous + step, row, step):
                result[r, col] = ink
            if work[row, col] == bg:
                result[row, col] = ink
                following.add(col)
            else:
                for delta in [-step, step]:
                    x = col + delta
                    while 0 <= x < work.shape[1]:
                        result[row - step, x] = ink
                        if work[row, x] == bg:
                            result[row, x] = ink
                            following.add(x)
                            break
                        x += delta
        active = following
        previous = row
    for col in active:
        for r in range(previous + step, work.shape[0], step):
            result[r, col] = ink
    if reversed:
        result = np.flipud(result)
    if transposed:
        result = result.T
    return result.copy()

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    scale = int(round(params['rule'][1]))
    direction = int(round(params['rule'][2]))
    anchor = int(round(params['rule'][3]))
    values = grid.flatten()
    size = len(values) * int(np.count_nonzero(values != background)) * scale
    if size <= 0 or size > 30:
        return grid.copy()
    result = np.full((size, size), background, dtype=int)
    for row in range(size):
        shift = direction * (size - anchor - row)
        for index in range(len(values)):
            column = index + shift
            if 0 <= column < size:
                result[row, column] = values[index]
    return result

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    radius = int(round(params['rule'][1]))
    out = grid.copy()
    objects = []
    for value in np.unique(grid):
        color = int(value)
        if color == bg:
            continue
        pending = set((int(p[0]), int(p[1])) for p in np.argwhere(grid == color))
        while pending:
            seed = min(pending)
            pending.remove(seed)
            points = [seed]
            queue = [seed]
            while queue:
                current = queue.pop()
                neighbors = []
                for point in pending:
                    if abs(point[0] - current[0]) <= radius and abs(point[1] - current[1]) <= radius:
                        neighbors.append(point)
                for point in neighbors:
                    pending.remove(point)
                    points.append(point)
                    queue.append(point)
            objects.append((color, points))
    if not objects:
        return out
    template_points = objects[0][1]
    for color, points in objects:
        if len(points) > len(template_points):
            template_points = points
    top = min(point[0] for point in template_points)
    left = min(point[1] for point in template_points)
    template = [(point[0] - top, point[1] - left) for point in template_points]
    height, width = grid.shape
    for color, points in objects:
        anchor = min(points)
        best_origin = None
        best_completed = None
        for offset in template:
            origin = (anchor[0] - offset[0], anchor[1] - offset[1])
            completed = set((origin[0] + point[0], origin[1] + point[1]) for point in template)
            valid = True
            for point in points:
                if point not in completed:
                    valid = False
                    break
            if not valid:
                continue
            for row, column in completed:
                if row < 0 or column < 0 or row >= height or column >= width:
                    valid = False
                    break
                if grid[row, column] != bg and grid[row, column] != color:
                    valid = False
                    break
            if valid:
                if best_origin is None or origin < best_origin:
                    best_origin = origin
                    best_completed = completed
        if best_completed is not None:
            for row, column in best_completed:
                out[row, column] = color
    return out
